insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('admin-navarra:14-ba74b06871','admin-navarra',14,'Cuando el último día del plazo sea inhábil:','["Se entenderá vencido el último día hábil anterior", "Se entenderá prorrogado al primer día hábil siguiente", "Se entenderá prorrogado al tercer día hábil siguiente", "El plazo vence ese mismo día"]'::jsonb,1,'Art. 30.5 Ley 39/2015','Se prorroga al primer día hábil siguiente.',null),
('admin-navarra:14-994acece81','admin-navarra',14,'Cuando la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente:','["No sucede, debiendo iniciar un nuevo procedimiento en el plazo de diez días", "Solo sucede si todavía no se ha abierto la fase de instrucción", "Sucederá en tal condición cualquiera que sea el estado del procedimiento", "Sucederá en tal condición solo si el procedimiento no ha concluido la fase de audiencia a los interesados"]'::jsonb,2,'Art. 4.3 Ley 39/2015','Sucede en la condición de interesado en cualquier estado del procedimiento.',null),
('admin-navarra:14-a797f20dff','admin-navarra',14,'Las asociaciones y organizaciones representativas de intereses económicos y sociales son titulares de:','["Intereses individuales de cada uno de sus asociados", "Intereses legítimos colectivos en los términos que la ley reconozca", "Derechos fundamentales propios en todo procedimiento administrativo que afecte a sus asociados o al sector", "Ningún interés"]'::jsonb,1,'Art. 4.2 Ley 39/2015','Son titulares de intereses legítimos colectivos.',null),
('admin-navarra:14-69094497aa','admin-navarra',14,'La resolución del procedimiento se dictará:','["Por escrito en papel, firmado por el titular del órgano", "Electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento", "Electrónicamente o en papel, a elección del órgano, garantizando solo la identidad del firmante y no la integridad del documento", "Verbalmente, con constancia en acta"]'::jsonb,1,'Art. 88.4 Ley 39/2015','La resolución se dicta electrónicamente.',null),
('admin-navarra:14-58aacd8c90','admin-navarra',14,'¿Quién puede acordar un período de información pública?','["El órgano al que corresponda la resolución del procedimiento, cuando su naturaleza lo requiera", "El instructor del procedimiento, a petición de cualquier interesado y siempre que lo autorice el órgano superior jerárquico", "Cualquier interesado, comunicándolo al órgano instructor, siempre que lo considere útil para su defensa", "El órgano que inició el procedimiento, solo en los procedimientos sancionadores"]'::jsonb,0,'Art. 83.1 Ley 39/2015','Lo acuerda el órgano competente para resolver.',null),
('admin-navarra:14-8730e9d477','admin-navarra',14,'Excepcionalmente, cuando al iniciar el procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos, esta podrá realizarse en una fase posterior mediante:','["Una propuesta de resolución que deberá notificarse a los interesados", "La elaboración de un Pliego de cargos, que deberá ser notificado a los interesados", "La elaboración de un Pliego de cargos, que no se notifica a los interesados hasta la propuesta de resolución definitiva del instructor", "Un nuevo acuerdo de iniciación"]'::jsonb,1,'Art. 64.3 Ley 39/2015','Se elabora un Pliego de cargos que se notifica a los interesados.',null),
('admin-navarra:14-25258cb637','admin-navarra',14,'NO será inmediatamente ejecutiva la resolución:','["De un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición", "De un procedimiento sancionador contra la que quepa recurso de alzada, pero no si solo cabe el potestativo de reposición", "De una solicitud de licencia que haya sido estimada", "De un recurso de alzada"]'::jsonb,0,'Art. 98.1 b) Ley 39/2015','Las sanciones no son ejecutivas mientras quepa recurso administrativo.',null),
('admin-navarra:14-5210d6fd2e','admin-navarra',14,'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad:','["Se reduce la sanción a la mitad de forma automática", "Se archiva el procedimiento sin imponer sanción, si el infractor paga voluntariamente", "Se podrá resolver el procedimiento con la imposición de la sanción que proceda", "Se podrá resolver el procedimiento sin imponer sanción, salvo que la infracción sea muy grave o el infractor sea reincidente"]'::jsonb,2,'Art. 85.1 Ley 39/2015','El reconocimiento permite resolver con la sanción procedente.',null),
('admin-navarra:14-fdc3e7b27a','admin-navarra',14,'La AGE, las CCAA y las Entidades Locales dispondrán de:','["Un registro electrónico general de apoderamientos", "Un registro de representantes en papel", "Un registro notarial propio", "Un registro único estatal compartido obligatoriamente"]'::jsonb,0,'Art. 6.1 Ley 39/2015','Cada una dispone de un registro electrónico general de apoderamientos.',null),
('admin-navarra:14-ba2b47ef6a','admin-navarra',14,'La ejecución subsidiaria procede respecto de actos que:','["Impongan obligaciones de no hacer o de soportar, previo apercibimiento al obligado", "Impongan al obligado el pago de cantidades líquidas", "Sean personalísimos de hacer y el obligado se niegue a realizarlos en el plazo fijado", "Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado"]'::jsonb,3,'Art. 102.1 Ley 39/2015','Cabe cuando el acto no es personalísimo y otro sujeto puede realizarlo.',null),
('admin-navarra:14-8a0221c9b8','admin-navarra',14,'Si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones:','["Se tendrá por decaído su derecho y se archivará el procedimiento", "Se tendrá por realizado el trámite", "Se ampliará de oficio el plazo para que puedan reconsiderar su decisión, que no será vinculante hasta su vencimiento", "Se suspenderá el procedimiento"]'::jsonb,1,'Art. 82.3 Ley 39/2015','El trámite se tiene por realizado.',null),
('admin-navarra:14-b3f9886a37','admin-navarra',14,'En los casos de estimación por silencio, la resolución expresa posterior:','["Podrá ser desestimatoria si así lo aconseja el interés público", "Deberá someterse a dictamen previo del Consejo de Estado", "Solo podrá dictarse de ser confirmatoria del mismo", "Podrá ser confirmatoria o desestimatoria, según el resultado de la instrucción y las alegaciones de los interesados"]'::jsonb,2,'Art. 24.3 a) Ley 39/2015','La resolución expresa posterior a la estimación por silencio solo puede confirmarla.',null),
('admin-navarra:14-bddb342f4e','admin-navarra',14,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Quince días", "Diez días", "Cinco días", "Un mes"]'::jsonb,0,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('admin-navarra:14-fa1505ee81','admin-navarra',14,'Son interesados en el procedimiento, según el art. 4.1 a):','["Cualquier ciudadano, sin necesidad de acreditar interés alguno", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado", "Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos"]'::jsonb,3,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('admin-navarra:14-4491b3cb46','admin-navarra',14,'Contra el acuerdo que resuelva sobre la ampliación del plazo máximo de resolución:','["Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "No cabrá recurso alguno", "Cabe recurso de alzada"]'::jsonb,2,'Art. 23.2 Ley 39/2015','Ese acuerdo no es recurrible.',null),
('admin-navarra:14-662fac92e7','admin-navarra',14,'La ampliación excepcional del plazo máximo de resolución no podrá ser superior:','["A la mitad del plazo establecido para la tramitación del procedimiento", "Al plazo establecido para la tramitación del procedimiento", "A diez días hábiles", "A un año, cualquiera que sea el plazo inicial"]'::jsonb,1,'Art. 23.1 Ley 39/2015','Contra el acuerdo de ampliación no cabe recurso.',null),
('admin-navarra:14-6c7b467399','admin-navarra',14,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Se tramitará en la lengua cooficial", "Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,3,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('admin-navarra:14-662ed2e207','admin-navarra',14,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Diez días a partir del siguiente al de la notificación del correspondiente acto", "Cinco días a partir del siguiente al de la notificación", "Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,0,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.',null),
('admin-navarra:14-e12a733a64','admin-navarra',14,'La ejecución forzosa de los actos administrativos se efectuará:','["Solo con autorización judicial previa", "Siempre mediante compulsión sobre las personas", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual", "Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('admin-navarra:14-a6e9bafb40','admin-navarra',14,'La ampliación de un plazo y su solicitud deberán producirse:','["Solo el último día del plazo de que se trate", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa", "En cualquier momento"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('admin-navarra:14-2406460e85','admin-navarra',14,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio o a solicitud del interesado", "Solo de oficio, por propia iniciativa del órgano", "De oficio, a solicitud del interesado o por orden judicial", "Solo a solicitud"]'::jsonb,0,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('admin-navarra:14-6aba11bce3','admin-navarra',14,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["En ningún caso", "Sí, si lo autoriza el superior", "Sí, cuando la ley sea oscura", "Sí, en los procedimientos de oficio"]'::jsonb,0,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('admin-navarra:14-be9f8edeff','admin-navarra',14,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["El infractor sea reincidente y reconozca su responsabilidad", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave", "La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('admin-navarra:14-949e224879','admin-navarra',14,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Un mes", "Quince días", "Siete días", "Tres meses"]'::jsonb,1,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('admin-navarra:14-3ee60e0861','admin-navarra',14,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación de no hacer", "Una cantidad líquida", "Una obligación de soportar", "Una obligación personalísima"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('admin-navarra:14-9b264df556','admin-navarra',14,'También producirá la terminación del procedimiento:','["La falta de crédito presupuestario adecuado y suficiente", "La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo"]'::jsonb,1,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('admin-navarra:14-82f21455f9','admin-navarra',14,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Por el instructor, a propuesta del Consejo de Estado", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,3,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('admin-navarra:14-989df206ca','admin-navarra',14,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La culpa del funcionario causante del daño", "La sanción disciplinaria del empleado público responsable", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La cuantía y el modo de indemnización"]'::jsonb,3,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('admin-navarra:14-c0db6b50d6','admin-navarra',14,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Libremente y sin necesidad de motivación", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Solo con autorización judicial", "Motivadamente, en cualquier supuesto, sin necesidad de previsión legal"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('admin-navarra:14-bce235464e','admin-navarra',14,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial", "No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Se refieran a sanciones de cuantía inferior a 3.000 euros", "Lo autorice un juez"]'::jsonb,1,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('admin-navarra:14-d1328bd137','admin-navarra',14,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin informe favorable del Consejo de Estado u órgano consultivo equivalente", "Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico", "Sin autorización judicial en todo caso"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('admin-navarra:14-ba182abc51','admin-navarra',14,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir todos los plazos a cinco días, incluidos los de recursos", "Suprimir los recursos administrativos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos", "Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos"]'::jsonb,3,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('admin-navarra:14-128c7d7da9','admin-navarra',14,'Solicitado el certificado acreditativo del silencio, este deberá emitirse en el plazo máximo de:','["Tres meses", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 24.4 Ley 39/2015','El certificado del silencio se emite en un máximo de quince días.',null),
('admin-navarra:14-d74ba9329a','admin-navarra',14,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada", "Sean improcedentes a su juicio, sin necesidad de motivar el rechazo ni notificarlo a los interesados", "Se propongan fuera del plazo de diez días"]'::jsonb,1,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('admin-navarra:14-b848d95c2c','admin-navarra',14,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo expira el último día del mes", "El plazo se amplía 10 días", "El plazo expira el primer día del mes siguiente", "El plazo se considera vencido el día 28"]'::jsonb,0,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('admin-navarra:14-8c12fd5cde','admin-navarra',14,'El procedimiento está sometido al principio de:','["Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos", "Secreto de las actuaciones", "Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel"]'::jsonb,1,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.',null),
('admin-navarra:14-5a075f4364','admin-navarra',14,'En la petición de un informe se concretará:','["El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita", "El sentido que debe tener el informe y el plazo para emitirlo", "El nombre del funcionario que debe emitirlo"]'::jsonb,1,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('admin-navarra:14-6f44b1df01','admin-navarra',14,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se comunicará a dichas personas la tramitación del procedimiento", "No se les comunica nada hasta la resolución, que se les notifica", "Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento"]'::jsonb,0,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('admin-navarra:14-a5ea67e878','admin-navarra',14,'La Administración está obligada a dictar resolución expresa y a notificarla:','["Solo en los procedimientos sancionadores", "En todos los procedimientos, cualquiera que sea su forma de iniciación", "Solo en los procedimientos iniciados a solicitud del interesado", "En todos los procedimientos, salvo en los iniciados de oficio, en que basta la caducidad"]'::jsonb,1,'Art. 21.1 Ley 39/2015','La obligación de resolver alcanza a todos los procedimientos, salvo las excepciones legales.',null),
('admin-navarra:14-1a47f1b98c','admin-navarra',14,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se aplica el calendario del órgano", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso", "Se considerará hábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('admin-navarra:14-3a0d888a0a','admin-navarra',14,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Lo soliciten todos los interesados por escrito", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('admin-navarra:14-db2e91941c','admin-navarra',14,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo", "Quince días hábiles", "Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran"]'::jsonb,3,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('admin-navarra:14-4b820f64c6','admin-navarra',14,'Los interesados que conozcan datos que permitan identificar a otros interesados que no hayan comparecido en el procedimiento:','["Tienen prohibido comunicarlos por razones de protección de datos", "Pueden comunicarlos voluntariamente, sin estar obligados a ello", "Tienen el deber de proporcionárselos a la Administración actuante", "Solo deben comunicarlos ante un juez"]'::jsonb,2,'Art. 18.2 Ley 39/2015','Existe el deber de proporcionar esos datos a la Administración.',null),
('admin-navarra:14-05c6406ba5','admin-navarra',14,'El incumplimiento de la obligación de dictar resolución expresa en plazo dará lugar a:','["La nulidad de pleno derecho del procedimiento", "Una sanción al interesado", "La estimación automática de la solicitud en todo caso, sin ninguna otra consecuencia para el órgano o para el personal responsable", "La exigencia de responsabilidad disciplinaria, sin perjuicio de la que hubiere lugar de acuerdo con la normativa aplicable"]'::jsonb,3,'Art. 21.6 Ley 39/2015','El personal y los titulares de órganos son responsables directos y responden disciplinariamente.',null),
('admin-navarra:14-5f839e7151','admin-navarra',14,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento del procedimiento anterior al trámite de audiencia", "En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "Solo en los diez primeros días desde el inicio del procedimiento"]'::jsonb,0,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('admin-navarra:14-8dc00548d1','admin-navarra',14,'Deberá acreditarse la representación para:','["Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos", "Pedir información general sobre los procedimientos", "Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general"]'::jsonb,0,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('admin-navarra:14-4d6053564c','admin-navarra',14,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria", "Se archiva el procedimiento", "Se resuelve igualmente según la propuesta de resolución", "El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada"]'::jsonb,0,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('admin-navarra:14-59f51a63e0','admin-navarra',14,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "El 30 % solo por pronto pago", "El 10 %, no acumulable", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí"]'::jsonb,3,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('admin-navarra:14-47319db3e5','admin-navarra',14,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["Suspenden la tramitación, salvo la abstención", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "No suspenderán la tramitación del procedimiento, salvo la recusación", "Suspenden siempre la tramitación"]'::jsonb,2,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('admin-navarra:14-a30f6ff55b','admin-navarra',14,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder especial para actuar ante los juzgados y tribunales penales en nombre del poderdante, en cualquier procedimiento", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('admin-navarra:14-ea267faea8','admin-navarra',14,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["Todos los recursos de un mismo interesado frente a actos distintos", "La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites de un mismo interesado, aunque sea obligado su cumplimiento sucesivo", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo"]'::jsonb,3,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('admin-navarra:14-e47e4ccbeb','admin-navarra',14,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Las Comunidades Autónomas cuando afecten a varias provincias", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,2,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('admin-navarra:14-bee4d78d32','admin-navarra',14,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Obligaciones no personalísimas de hacer que puedan cumplirse por otro", "Cobrar cantidades líquidas", "Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar"]'::jsonb,3,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('admin-navarra:14-19b5a1dab3','admin-navarra',14,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["De tres días", "De un mes", "No superior a quince días", "No inferior a veinte días"]'::jsonb,2,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('admin-navarra:14-62b3e9c686','admin-navarra',14,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Las realiza el denunciante y el órgano competente, respectivamente", "Se tramitan como una sola fase", "Se encomendarán a órganos distintos"]'::jsonb,3,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('admin-navarra:14-fecb17cbf9','admin-navarra',14,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "No puede asistir a su práctica", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('admin-navarra:14-49de1e4524','admin-navarra',14,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El sentido de la resolución que deba dictarse", "La sanción que corresponda imponer, el órgano competente para resolver, el instructor designado y el plazo máximo para dictar resolución", "El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,3,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('admin-navarra:14-61341a2bb1','admin-navarra',14,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva", "Por el doble de su coste, en concepto de sanción", "Nunca, porque los gastos los asume siempre la Administración que ejecuta", "Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional"]'::jsonb,0,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('admin-navarra:14-0aaf4f83c6','admin-navarra',14,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Todos los acuerdos convencionales que pongan fin a cualquier procedimiento", "Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,2,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null),
('admin-navarra:14-29eee13a18','admin-navarra',14,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Ministro respectivo", "El Subsecretario", "El Presidente del Gobierno", "El Delegado del Gobierno"]'::jsonb,0,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('admin-navarra:14-41c22df4a6','admin-navarra',14,'Cuando se soliciten informes preceptivos a un órgano, el plazo máximo para resolver puede suspenderse por el tiempo que medie entre la petición y la recepción del informe, sin que pueda exceder de:','["Tres meses", "Seis meses", "Un mes", "Diez días"]'::jsonb,0,'Art. 22.1 d) Ley 39/2015','Esta suspensión no puede exceder en ningún caso de tres meses.',null),
('admin-navarra:14-aafcd3f75f','admin-navarra',14,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Se personan en el procedimiento en tanto no haya recaído resolución definitiva", "Lo solicitan antes del inicio del procedimiento", "Se personan en cualquier momento, incluso después de la resolución definitiva", "Lo autoriza el instructor"]'::jsonb,0,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('admin-navarra:14-9a596eb5d4','admin-navarra',14,'En ningún caso se podrá imponer una sanción:','["Sin que se haya tramitado el oportuno procedimiento", "A una persona jurídica", "Superior a 600 euros sin autorización judicial", "Sin que el infractor esté asistido de abogado"]'::jsonb,0,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('admin-navarra:14-3454a24796','admin-navarra',14,'En caso de desestimación por silencio, la resolución expresa posterior:','["No puede dictarse", "Se adoptará por la Administración sin vinculación alguna al sentido del silencio", "Debe ser necesariamente desestimatoria, en coherencia con el sentido del silencio producido", "Solo puede ser confirmatoria"]'::jsonb,1,'Art. 24.3 b) Ley 39/2015','En la estimación por silencio, en cambio, la resolución posterior solo puede ser confirmatoria.',null),
('admin-navarra:14-c0f9b3ba2d','admin-navarra',14,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Cinco días", "Quince días", "Diez días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('admin-navarra:14-2233101b5a','admin-navarra',14,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los españoles mayores de edad", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('admin-navarra:14-a98457871a','admin-navarra',14,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender desestimadas sus pretensiones por silencio administrativo", "Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Exigir una indemnización automática"]'::jsonb,0,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('admin-navarra:14-218f4ca066','admin-navarra',14,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "Es obligatoria para poder recurrir después la resolución", "Convierte en interesado al compareciente", "No otorga, por sí misma, la condición de interesado"]'::jsonb,3,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null),
('admin-navarra:14-d383bad3dc','admin-navarra',14,'Contra el acuerdo de acumulación de procedimientos:','["No procederá recurso alguno", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "Cabe recurso de alzada"]'::jsonb,0,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('admin-navarra:14-2cf708f131','admin-navarra',14,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "Se mantiene la tramitación simplificada", "Se mantiene la tramitación simplificada si el órgano lo motiva", "La Administración deberá seguir la tramitación ordinaria"]'::jsonb,3,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('admin-navarra:14-8468b82170','admin-navarra',14,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Lo decida motivadamente el instructor del procedimiento", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada", "Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('admin-navarra:14-7fbbcf3314','admin-navarra',14,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Deberá archivar el procedimiento", "Deberá pedir dictamen al Consejo de Estado"]'::jsonb,0,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('admin-navarra:14-fcf146e379','admin-navarra',14,'Si un informe preceptivo no se emite en plazo:','["Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable", "Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se archiva el procedimiento"]'::jsonb,2,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('admin-navarra:14-df315c9ee1','admin-navarra',14,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Siempre, cualquiera que sea su número de miembros", "Cuando tengan más de 20 miembros", "Cuando la ley así lo declare expresamente", "Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen"]'::jsonb,2,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('admin-navarra:14-b27ca15860','admin-navarra',14,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, sin posibilidad de recurso", "Un mes desde su presentación, con recurso de alzada", "Diez días desde su presentación, con recurso de alzada", "Cinco días desde su presentación, con recurso potestativo de reposición"]'::jsonb,0,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('admin-navarra:14-3ce3addf69','admin-navarra',14,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer", "La sanción disciplinaria al funcionario responsable y la cuantía de la indemnización", "La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración"]'::jsonb,2,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('admin-navarra:14-71d1f37d81','admin-navarra',14,'No se podrán adoptar medidas provisionales que:','["Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia", "Se adopten una vez iniciado el procedimiento, sin audiencia previa del interesado", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes"]'::jsonb,3,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('admin-navarra:14-da72c7b067','admin-navarra',14,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["Nunca, porque la tramitación simplificada lo suprime en todo caso", "Siempre, como en la tramitación ordinaria", "Lo pida cualquier tercero que no sea interesado", "La resolución vaya a ser desfavorable para el interesado"]'::jsonb,3,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('admin-navarra:14-954e18d620','admin-navarra',14,'Los términos y plazos establecidos en las leyes obligan:','["Solo a la Administración, que debe resolver en el plazo máximo", "Solo a los interesados, que pierden su derecho si no los cumplen", "A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,2,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null),
('admin-navarra:14-c75a42154a','admin-navarra',14,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["De uso obligatorio por los interesados", "Solo orientativos", "Exclusivos para personas jurídicas", "De uso voluntario"]'::jsonb,0,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('admin-navarra:14-46ece88822','admin-navarra',14,'Los plazos expresados en días se contarán:','["Desde que el interesado tenga conocimiento efectivo del acto", "Desde el mismo día de la notificación o publicación del acto", "Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,3,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('admin-navarra:14-ef23f28c38','admin-navarra',14,'En los procedimientos tramitados por la AGE, la lengua será:','["Siempre la lengua cooficial del territorio donde tenga su sede el órgano", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,2,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('admin-navarra:14-363dce95b0','admin-navarra',14,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El más rápido para la Administración", "El que elija el interesado de entre los admisibles", "El más económico para la Administración actuante", "El menos restrictivo de la libertad individual"]'::jsonb,3,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('admin-navarra:14-a411a1281f','admin-navarra',14,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Un año, renovable por periodos iguales", "Cinco años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('admin-navarra:14-163732cb71','admin-navarra',14,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Los recursos contencioso-administrativos", "Las acciones posesorias", "Los recursos de alzada", "Las reclamaciones de responsabilidad"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('admin-navarra:14-332e8092d1','admin-navarra',14,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una copia firmada por el titular del órgano destinatario", "La devolución de las tasas abonadas", "Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación"]'::jsonb,3,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('admin-navarra:14-f15ac9015a','admin-navarra',14,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Un mes desde que fueron notificados", "Quince días desde que fueron notificados", "Diez días desde que fueron notificados"]'::jsonb,3,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null),
('admin-navarra:14-d0e67e022a','admin-navarra',14,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno", "Nada, la obligación se extingue", "Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil"]'::jsonb,0,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('admin-navarra:14-58d831f690','admin-navarra',14,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso contencioso-administrativo inmediato", "Cabe recurso de alzada", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('admin-navarra:14-b6bb0d9f14','admin-navarra',14,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["El período de prueba", "Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento", "El trámite de información pública"]'::jsonb,1,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('admin-navarra:14-14406c9b18','admin-navarra',14,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["La sanción que corresponda sea muy grave", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,2,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('admin-navarra:14-d2ec5a62b3','admin-navarra',14,'Las Administraciones deben publicar y mantener actualizadas en el portal web:','["Las nóminas de todos sus empleados", "Las resoluciones judiciales que les afecten", "Las relaciones de procedimientos de su competencia, con indicación de los plazos máximos de duración y de los efectos del silencio administrativo", "Las relaciones de procedimientos de su competencia, con los datos de los interesados y el estado de tramitación de cada expediente"]'::jsonb,2,'Art. 21.4 Ley 39/2015','Deben publicar los procedimientos, sus plazos máximos y los efectos del silencio.',null),
('admin-navarra:14-fab6bc129a','admin-navarra',14,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se entiende estimada la reclamación", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,3,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('admin-navarra:14-87dcf86284','admin-navarra',14,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro del mes siguiente a su adopción", "Dentro de los tres meses siguientes", "Dentro de los quince días siguientes a su adopción", "Dentro de los diez días siguientes a su adopción"]'::jsonb,2,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.',null),
('admin-navarra:14-b46fc5d764','admin-navarra',14,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento", "No tienen valor probatorio", "Harán prueba de estos salvo que se acredite lo contrario"]'::jsonb,3,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('admin-navarra:14-db1eb11716','admin-navarra',14,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Tres meses desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Seis meses desde el inicio del procedimiento", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('admin-navarra:14-db807559a2','admin-navarra',14,'Se entiende por propia iniciativa:','["La petición de un órgano sin competencia de iniciación", "La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,2,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('admin-navarra:14-ef88f1d98a','admin-navarra',14,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que lo pida el denunciante", "Con independencia de su diferente valoración jurídica"]'::jsonb,3,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('admin-navarra:14-6ff8836a71','admin-navarra',14,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Un mes", "Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('admin-navarra:14-94a9eee011','admin-navarra',14,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Mediante circular o instrucción interna", "Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,3,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('admin-navarra:14-f42604ff9e','admin-navarra',14,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Solo si el instructor lo propone y el interesado no se opone", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Salvo que sea una persona jurídica", "Sin que en ningún caso pueda agravar su situación inicial"]'::jsonb,3,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('admin-navarra:14-0a849fde3d','admin-navarra',14,'La presentación de una denuncia:','["Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "Obliga a iniciar el procedimiento y a sancionar", "No confiere, por sí sola, la condición de interesado en el procedimiento", "Requiere asistencia de abogado"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('admin-navarra:14-f5dec5907a','admin-navarra',14,'Según el art. 62.1, se entiende por denuncia:','["La solicitud de un interesado para que se inicie un procedimiento en su favor", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "La orden de un superior"]'::jsonb,1,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('admin-navarra:14-0ec499167b','admin-navarra',14,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "6.000 euros", "100.000 euros", "30.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('admin-navarra:14-214f21fff8','admin-navarra',14,'En el despacho de los expedientes se guardará:','["El orden que prefiera el funcionario responsable", "El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('admin-navarra:14-9a1fcdcd6c','admin-navarra',14,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal", "Solicitar autorización judicial", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Notificar al particular interesado la resolución que autorice la actuación administrativa"]'::jsonb,3,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('admin-navarra:14-cdfec1df20','admin-navarra',14,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "A los tres meses de su presentación si la Administración no se opone", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('admin-navarra:14-3e51ce252f','admin-navarra',14,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["No está permitido una vez iniciado el procedimiento", "Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "Solo afectará a aquellos que la hubiesen formulado", "Afectará a todos los interesados, salvo que alguno inste la continuación en diez días"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('admin-navarra:14-a9a27f6680','admin-navarra',14,'Para los actos y gestiones de mero trámite, la representación:','["No está permitida", "Se presumirá", "Debe acreditarse ante notario", "Debe inscribirse en el registro de apoderamientos"]'::jsonb,1,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('admin-navarra:14-3c38d13705','admin-navarra',14,'Los documentos electrónicos deben conservarse en un formato que permita garantizar:','["Su autenticidad, integridad y conservación, y su consulta con independencia del tiempo transcurrido", "Su consulta durante los cinco años siguientes a la finalización del procedimiento, plazo tras el cual pueden eliminarse sin más trámite", "Su conversión obligatoria a papel cuando el procedimiento termine", "Su integridad mientras el procedimiento esté en tramitación, pero no después"]'::jsonb,0,'Art. 17.2 Ley 39/2015','El art. 17.2 exige un formato que garantice autenticidad, integridad y conservación, y la consulta sin importar el tiempo transcurrido.',null),
('admin-navarra:14-d1d37773bb','admin-navarra',14,'La presentación de documentos en el registro electrónico en un día inhábil se entiende realizada:','["Al día siguiente, aunque también sea inhábil", "El último día hábil anterior", "En el mismo día inhábil, a todos los efectos", "En la primera hora del primer día hábil siguiente, salvo que una norma permita expresamente la recepción en día inhábil"]'::jsonb,3,'Art. 31.2 b) Ley 39/2015','Los documentos se consideran presentados por el orden de hora efectiva en el que lo fueron en el día inhábil.',null),
('admin-navarra:14-56a176717a','admin-navarra',14,'El registro electrónico de cada Administración permite la presentación de documentos:','["Todos los días del año, durante las veinticuatro horas", "En días hábiles, pero durante las veinticuatro horas de cada día", "En días hábiles, de 9 a 14 horas, como las oficinas presenciales", "Todos los días del año, pero solo en el horario de atención al público"]'::jsonb,0,'Art. 31.2 a) Ley 39/2015','El cómputo de plazos se rige por la fecha y hora oficial de la sede electrónica.',null),
('admin-navarra:14-2421923be3','admin-navarra',14,'Cada Administración debe mantener un archivo electrónico único de:','["Todos los escritos en papel presentados por los ciudadanos", "Los documentos electrónicos que correspondan a procedimientos finalizados", "Las resoluciones judiciales que le afecten", "Los expedientes de personal de todos sus funcionarios y del personal laboral a su servicio"]'::jsonb,1,'Art. 17.1 Ley 39/2015','Los documentos se conservan en un formato que permita garantizar su autenticidad, integridad y conservación.',null),
('admin-navarra:14-97ad75f120','admin-navarra',14,'¿Qué plazo máximo de resolución puede fijar, como regla, la norma reguladora de un procedimiento foral?','["Un año, salvo ley foral", "Seis meses, salvo ley o Derecho de la Unión Europea", "Cuatro meses, sin excepciones", "Tres meses, salvo ley foral"]'::jsonb,1,'Art. 117 LF 11/2019 Navarra','El plazo no puede exceder de seis meses salvo que una ley o ley foral establezca otro o lo prevea el Derecho de la UE.',null),
('admin-navarra:14-6a8b115b3e','admin-navarra',14,'Si la norma reguladora de un procedimiento foral no fija plazo para resolver, ¿cuál es?','["Tres meses", "Un mes", "Seis meses", "Dos meses"]'::jsonb,0,'Art. 117 LF 11/2019 Navarra','Cuando la norma no fija plazo máximo, este es de tres meses.',null),
('admin-navarra:14-cbef9449a5','admin-navarra',14,'En defecto de atribución expresa, ¿quién inicia y resuelve el procedimiento sancionador en la Administración foral?','["El Director General competente", "El Gobierno de Navarra", "La persona titular del Departamento competente por razón de la materia", "El Jefe del Servicio instructor"]'::jsonb,2,'Art. 120 LF 11/2019 Navarra','En defecto de atribución expresa, corresponde a la persona titular del departamento competente por razón de la materia.',null),
('admin-navarra:14-96a98cd849','admin-navarra',14,'¿Qué reducción se aplica en Navarra a una sanción pecuniaria por pago voluntario antes de la resolución?','["El 30 %", "El 20 %", "El 25 %", "El 50 %"]'::jsonb,1,'Art. 121 LF 11/2019 Navarra','Se aplica un 30 % por reconocimiento de responsabilidad en plazo y un 20 % por pago voluntario antes de la resolución.',null),
('admin-navarra:14-260a90f82b','admin-navarra',14,'¿Qué reducción se aplica en Navarra por reconocer la responsabilidad en el plazo del acuerdo de iniciación?','["El 15 %", "El 20 %", "El 40 %", "El 30 %"]'::jsonb,3,'Art. 121 LF 11/2019 Navarra','El 30 % sobre el importe de la sanción en caso de reconocimiento de la responsabilidad en plazo.',null),
('admin-navarra:14-67dd9c6b11','admin-navarra',14,'¿Quién resuelve los procedimientos de responsabilidad patrimonial en la Administración foral, salvo en organismos autónomos?','["La persona titular del Departamento cuya actuación haya podido generarla", "El Gobierno de Navarra", "El Consejo de Navarra", "El Departamento competente en hacienda"]'::jsonb,0,'Art. 122 LF 11/2019 Navarra','Corresponde a la persona titular del Departamento cuya actuación haya podido generar la responsabilidad.',null),
('admin-navarra:15-a8cb587dd8','admin-navarra',15,'¿A qué Administraciones se aplica el Estatuto del Personal al servicio de las Administraciones Públicas de Navarra?','["A la Administración foral, al Parlamento y a la Universidad Pública", "Solo a la Administración de la Comunidad Foral y sus organismos autónomos", "Solo a las entidades locales con más de 5.000 habitantes", "A la Administración de la Comunidad Foral, las entidades locales de Navarra y sus organismos públicos"]'::jsonb,3,'Art. 1 DFLeg 251/1993 Navarra','Se aplica a la Administración de la Comunidad Foral, a las entidades locales de Navarra y a los organismos públicos dependientes de unas y otras.',null),
('admin-navarra:15-2fd492461b','admin-navarra',15,'¿Qué personal sanitario queda excluido del Estatuto del Personal de Navarra?','["Solo el personal médico del Servicio Navarro de Salud", "Solo el personal laboral de los hospitales públicos", "El adscrito al Servicio Navarro de Salud-Osasunbidea y los funcionarios sanitarios municipales", "Ninguno, todo el personal sanitario se rige por el Estatuto"]'::jsonb,2,'Art. 2 DFLeg 251/1993 Navarra','Quedan excluidos el personal adscrito al Servicio Navarro de Salud-Osasunbidea y los funcionarios sanitarios municipales.',null),
('admin-navarra:15-d5b552aa08','admin-navarra',15,'¿Por qué normas se rige el personal al servicio de la Administración de Justicia en Navarra?','["Por el convenio colectivo del personal de Justicia", "Por la Ley Orgánica del Poder Judicial y las disposiciones del Estatuto que le sean aplicables", "Exclusivamente por el Estatuto Básico del Empleado Público", "Exclusivamente por el Estatuto del Personal de Navarra"]'::jsonb,1,'Art. 2 DFLeg 251/1993 Navarra','Está sujeto a la Ley Orgánica del Poder Judicial y a las disposiciones del Estatuto que le sean de aplicación.',null),
('admin-navarra:15-545ec7458b','admin-navarra',15,'¿Con qué especialidades se aplica el Estatuto al personal de las entidades locales de Navarra?','["Con las de la Ley 7/1985, Reguladora de las Bases del Régimen Local", "Con las de la Ley Foral 6/1990, de la Administración Local de Navarra", "Sin especialidades, en los mismos términos que a la Administración foral", "Con las que fije cada ayuntamiento en su reglamento orgánico"]'::jsonb,1,'Art. 2 DFLeg 251/1993 Navarra','Se aplica al personal de las entidades locales con las especificidades de la Ley Foral 6/1990, de la Administración Local de Navarra.',null),
('admin-navarra:15-081f99584d','admin-navarra',15,'¿Quiénes son funcionarios públicos según el Estatuto del Personal de Navarra?','["Quienes por nombramiento legal se incorporan con carácter permanente mediante una relación estatutaria", "Quienes ocupan cargos políticos de libre designación", "Quienes prestan servicios mediante contrato administrativo de duración determinada", "Quienes han superado un proceso selectivo, aunque no hayan sido nombrados"]'::jsonb,0,'Art. 3 DFLeg 251/1993 Navarra','Son funcionarios quienes, por nombramiento legal, se incorporan con carácter permanente mediante una relación de servicios profesionales sometida al Derecho Administrativo.',null),
('admin-navarra:15-c90ca529b1','admin-navarra',15,'¿En qué régimen puede ser el personal contratado de las Administraciones Públicas de Navarra?','["Administrativo, laboral o mercantil", "Solo administrativo", "Solo laboral", "Administrativo o laboral"]'::jsonb,3,'Art. 3 DFLeg 251/1993 Navarra','El personal contratado podrá serlo en régimen administrativo o laboral.',null),
('admin-navarra:15-e8d0b7fb3f','admin-navarra',15,'¿Quién tiene competencia para establecer el régimen del personal a su servicio según el Estatuto navarro?','["El Parlamento de Navarra mediante ley foral", "La Mesa General de negociación", "Cada una de las Administraciones Públicas de Navarra", "Solo el Gobierno de Navarra para todas ellas"]'::jsonb,2,'Art. 4 DFLeg 251/1993 Navarra','Cada Administración Pública de Navarra tiene plena competencia para establecer el régimen de su personal, conforme al Estatuto y sus reglamentos.',null),
('admin-navarra:15-2d64444598','admin-navarra',15,'¿Qué personal queda excluido del Estatuto del Personal al servicio de las Administraciones Públicas de Navarra?','["Los miembros de la Policía Foral", "El personal de las entidades locales de Navarra", "El personal de los organismos autónomos forales", "El personal eventual de la Administración foral"]'::jsonb,0,'Art. 2 DFLeg 251/1993 Navarra','Quedan excluidos, entre otros, los miembros de la Policía Foral y el personal del Servicio Navarro de Salud-Osasunbidea.',null),
('admin-navarra:15-aacbcfa331','admin-navarra',15,'Según el Estatuto del Personal de Navarra, ¿por quiénes está integrado el personal al servicio de las Administraciones Públicas de Navarra?','["Funcionarios, personal eventual y personal directivo profesional", "Funcionarios de carrera, funcionarios interinos y personal laboral", "Funcionarios públicos, personal eventual y personal contratado", "Funcionarios, personal directivo y personal laboral"]'::jsonb,2,'Art. 3 DFLeg 251/1993 Navarra','Lo integran los funcionarios públicos, el personal eventual y el personal contratado, que puede serlo en régimen administrativo o laboral.',null),
('admin-navarra:15-0a3bd719c6','admin-navarra',15,'¿Qué funciones ejerce el personal eventual según el Estatuto del Personal de Navarra?','["Funciones de carácter permanente en puestos vacantes", "Cargos políticos de libre designación o asistencia y asesoramiento a ellos", "Tareas de ejecución de programas temporales", "Funciones directivas profesionales en organismos autónomos y entidades públicas"]'::jsonb,1,'Art. 3 DFLeg 251/1993 Navarra','El personal eventual ejerce exclusivamente, con carácter temporal, cargos políticos de libre designación o funciones de asistencia o asesoramiento a ellos.',null),
('admin-navarra:16-854c07290b','admin-navarra',16,'¿Por qué sistemas se seleccionan los funcionarios de las Administraciones Públicas de Navarra?','["Concurso de méritos o libre designación", "Oposición libre o promoción interna exclusivamente", "Oposición, concurso-oposición o concurso", "Oposición o concurso-oposición"]'::jsonb,3,'Art. 5 DFLeg 251/1993 Navarra','La selección se realiza mediante convocatoria pública y pruebas selectivas por el sistema de oposición o concurso-oposición.',null),
('admin-navarra:16-903210387b','admin-navarra',16,'En el concurso-oposición del Estatuto navarro, ¿en qué consiste la fase de concurso?','["Exclusivamente en calificar los méritos alegados según el baremo de la convocatoria", "En una prueba práctica sobre el puesto de trabajo", "En un curso selectivo de formación", "En una entrevista personal sobre el currículo, valorada libremente por el tribunal"]'::jsonb,0,'Art. 5 DFLeg 251/1993 Navarra','La fase de concurso consiste exclusivamente en la calificación de los méritos alegados de acuerdo con el baremo de la convocatoria.',null),
('admin-navarra:16-92553f117c','admin-navarra',16,'¿Qué edad mínima exige el Estatuto del Personal de Navarra para participar en las pruebas selectivas?','["Veintiún años", "Dieciséis años", "Dieciocho años", "Diecisiete años"]'::jsonb,1,'Art. 7 DFLeg 251/1993 Navarra','Se requiere tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa.',null),
('admin-navarra:16-8d98bace8c','admin-navarra',16,'¿Dónde se publican las convocatorias de ingreso y sus bases en las Administraciones Públicas de Navarra?','["En el Boletín Oficial del Estado", "Solo en el tablón de anuncios de cada Administración", "En la sede electrónica, sin publicación en boletín", "En el Boletín Oficial de Navarra"]'::jsonb,3,'Art. 8 DFLeg 251/1993 Navarra','Las convocatorias y sus bases se publican en el BON y vinculan a la Administración, a los tribunales y a los aspirantes.',null),
('admin-navarra:16-e486943da6','admin-navarra',16,'¿Cuál de estos requisitos NO forma parte de la adquisición de la condición de funcionario en Navarra?','["Nombramiento publicado en el BON", "Superar las pruebas selectivas", "Superar un periodo de prácticas de un año", "Juramento o promesa y toma de posesión"]'::jsonb,2,'Art. 9 DFLeg 251/1993 Navarra','Se adquiere por superar las pruebas, nombramiento publicado en el BON, juramento o promesa y toma de posesión.',null),
('admin-navarra:16-4639684e96','admin-navarra',16,'¿Inhabilita la renuncia a la condición de funcionario para un nuevo ingreso en la función pública navarra?','["Sí, de forma definitiva", "Sí, durante cinco años", "No", "Sí, durante dos años"]'::jsonb,2,'Art. 11 DFLeg 251/1993 Navarra','La renuncia a la condición de funcionario no inhabilita para un nuevo ingreso en la función pública.',null),
('admin-navarra:16-4fa89d0c4c','admin-navarra',16,'¿En qué nivel se integran los funcionarios navarros que desarrollan tareas auxiliares con Graduado Escolar o equivalente?','["Nivel B", "Nivel E", "Nivel C", "Nivel D"]'::jsonb,3,'Art. 12 DFLeg 251/1993 Navarra','El nivel D desarrolla tareas auxiliares o análogas y exige Graduado Escolar, FP de primer grado o equivalente.',null),
('admin-navarra:16-87d0356646','admin-navarra',16,'¿Qué título exige el nivel C de los funcionarios de Navarra?','["Bachillerato, Formación Profesional de segundo grado o equivalente", "Graduado Escolar o Formación Profesional de primer grado", "Certificado de Escolaridad o equivalente", "Diplomado universitario o Formación Profesional de tercer grado"]'::jsonb,0,'Art. 12 DFLeg 251/1993 Navarra','El nivel C desempeña tareas de ejecución con título de Bachillerato, FP de segundo grado o equivalente.',null),
('admin-navarra:16-22d0938b91','admin-navarra',16,'¿En qué grado quedan encuadrados, como regla, los funcionarios navarros de nuevo ingreso?','["En el grado 2 del correspondiente nivel", "En el grado 1 del correspondiente nivel", "En el grado 3 si superan la oposición con nota alta", "En el grado que fije la convocatoria"]'::jsonb,1,'Art. 13 DFLeg 251/1993 Navarra','Quedan en el grado 1, salvo que su antigüedad reconocida les dé derecho a un grado superior.',null),
('admin-navarra:16-d4d85c6d99','admin-navarra',16,'¿Qué antigüedad se exige para la promoción de nivel por turno restringido en Navarra, además de la titulación?','["Ocho años en el mismo puesto", "Dos años de antigüedad reconocida", "Cinco años de antigüedad reconocida", "Tres años en el nivel inferior"]'::jsonb,2,'Art. 15 DFLeg 251/1993 Navarra','Se exige poseer la titulación y acreditar cinco años de antigüedad reconocida; para los niveles C, D y E puede suplirse con ocho años.',null),
('admin-navarra:16-fe065483a1','admin-navarra',16,'¿Cómo se reparten las vacantes entre turno libre y turno de promoción en cada convocatoria navarra?','["La primera a promoción, la segunda al libre y así alternativamente", "La primera al libre, la segunda a promoción y desde la tercera las impares a promoción", "Un tercio para promoción y el resto para el libre", "La mitad para cada turno, redondeando a favor del turno libre si el número es impar"]'::jsonb,1,'Art. 15 DFLeg 251/1993 Navarra','La primera, al turno libre; la segunda, al de promoción; a partir de la tercera, las impares a promoción y las pares al libre.',null),
('admin-navarra:16-09dc824f5e','admin-navarra',16,'¿Qué ocurre con las vacantes del turno de promoción que quedan desiertas?','["Quedan amortizadas", "Se proveen por libre designación", "Se convocan de nuevo por promoción", "Se acumulan a las del turno libre"]'::jsonb,3,'Art. 15 DFLeg 251/1993 Navarra','Las vacantes del turno restringido que queden desiertas se acumulan a las del turno libre.',null),
('admin-navarra:16-d28963e34f','admin-navarra',16,'¿Cuál de estas NO es una situación administrativa de los funcionarios de Navarra según el Estatuto?','["Expectativa de destino", "Servicios especiales", "Excedencia", "Suspensión"]'::jsonb,0,'Art. 22 DFLeg 251/1993 Navarra','Las situaciones son servicio activo, servicios especiales, excedencia y suspensión.',null),
('admin-navarra:16-ac878fe69a','admin-navarra',16,'¿En qué situación queda un funcionario navarro al que se confiere una comisión de servicios temporal?','["Excedencia voluntaria", "Servicio activo", "Excedencia especial", "Servicios especiales"]'::jsonb,1,'Art. 23 DFLeg 251/1993 Navarra','Están en servicio activo cuando se les confiere una comisión de servicios de carácter temporal.',null),
('admin-navarra:16-7981720fa1','admin-navarra',16,'¿En qué situación queda un funcionario navarro nombrado miembro del Gobierno de Navarra?','["Excedencia forzosa", "Excedencia voluntaria", "Servicios especiales", "Servicio activo"]'::jsonb,2,'Art. 24 DFLeg 251/1993 Navarra','Pasan a servicios especiales quienes accedan a la condición de miembros del Gobierno del Estado, de Navarra o de una comunidad autónoma.',null),
('admin-navarra:16-309b6a9692','admin-navarra',16,'¿En qué plazo debe reincorporarse un funcionario navarro tras cesar en la situación de servicios especiales?','["Un mes natural desde la publicación del cese", "Diez días hábiles", "Quince días", "Treinta días"]'::jsonb,3,'Art. 24 DFLeg 251/1993 Navarra','Deben reincorporarse a su plaza de origen dentro de los treinta días siguientes al cese.',null),
('admin-navarra:16-796b3fc15a','admin-navarra',16,'¿Qué clases de excedencia prevé el Estatuto del Personal de Navarra?','["Voluntaria, especial y forzosa", "Voluntaria, forzosa y por violencia de género únicamente", "Voluntaria, por cuidado de familiares y forzosa", "Voluntaria por interés particular y por agrupación familiar"]'::jsonb,0,'Art. 25 DFLeg 251/1993 Navarra','La excedencia podrá ser voluntaria, especial o forzosa.',null),
('admin-navarra:16-7f2f7e40bd','admin-navarra',16,'¿Cuál es la duración máxima de la excedencia especial por cada sujeto causante en Navarra?','["Cinco años", "Tres años", "Un año prorrogable", "Dos años"]'::jsonb,1,'Art. 27 DFLeg 251/1993 Navarra','La excedencia especial tiene una duración máxima de tres años por cada sujeto causante.',null),
('admin-navarra:16-0f2880f533','admin-navarra',16,'¿Hasta qué grado de parentesco permite la excedencia especial para cuidar a un familiar en Navarra?','["Segundo grado de consanguinidad o afinidad", "Cuarto grado de consanguinidad", "Primer grado de consanguinidad", "Tercer grado de consanguinidad o afinidad"]'::jsonb,0,'Art. 27 DFLeg 251/1993 Navarra','Procede para atender a un familiar a cargo hasta el segundo grado inclusive de consanguinidad o afinidad.',null),
('admin-navarra:16-0f730c4015','admin-navarra',16,'¿Qué efectos tiene la excedencia especial en Navarra sobre la antigüedad?','["Solo computa el primer año", "Computa solo a efectos de derechos pasivos", "Se computa todo el tiempo a efectos de antigüedad", "No se computa a ningún efecto"]'::jsonb,2,'Art. 27 DFLeg 251/1993 Navarra','Hay reserva de plaza, sin derechos económicos, y se computa todo el tiempo a efectos de antigüedad.',null),
('admin-navarra:16-8358be0789','admin-navarra',16,'¿Cuándo se declara la excedencia forzosa de un funcionario navarro?','["Cuando pasa a prestar servicios con carácter fijo en otra Administración Pública", "Cuando cuida de un hijo menor de tres años", "Cuando lo solicita por interés particular", "Cuando ejerce una actividad incompatible y no renuncia a ella"]'::jsonb,3,'Art. 28 DFLeg 251/1993 Navarra','Procede, entre otros casos, cuando el funcionario que ejerce una actividad incompatible no renuncia a ella.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('admin-navarra:16-c73f325ab7','admin-navarra',16,'¿Durante cuánto tiempo tienen reserva de plaza las funcionarias navarras en excedencia por violencia de género, sin prórrogas?','["Tres meses", "Un año", "Dieciocho meses", "Seis meses"]'::jsonb,3,'Art. 28 bis DFLeg 251/1993 Navarra','Durante los seis primeros meses tienen reserva de plaza, prorrogable por periodos de tres meses hasta dieciocho.',null),
('admin-navarra:16-0171bc9d3e','admin-navarra',16,'¿Cuál es el tiempo máximo de suspensión provisional durante la tramitación de un expediente disciplinario en Navarra?','["Un año", "Tres meses", "Seis meses", "Dieciocho meses"]'::jsonb,2,'Art. 29 DFLeg 251/1993 Navarra','La suspensión provisional durante un expediente disciplinario no puede exceder de seis meses.',null),
('admin-navarra:17-e0b6fc0911','admin-navarra',17,'¿Cuál es la duración máxima de la interinidad de un funcionario navarro en un puesto sin titular con reserva?','["Seis meses", "Un año", "Tres meses", "Dos años"]'::jsonb,1,'Art. 32 DFLeg 251/1993 Navarra','Salvo que la plaza tenga titular con reserva, la interinidad dura como máximo un año; después se declara vacante.',null),
('admin-navarra:17-eb418c85be','admin-navarra',17,'¿Desde cuándo cobra un funcionario navarro la diferencia de retribución del puesto que desempeña interinamente?','["Transcurridos tres meses, con efectos retroactivos desde el inicio", "Transcurridos seis meses, sin efectos retroactivos al comienzo de la interinidad", "Solo si la interinidad supera un año", "Desde el primer día, sin requisito de tiempo"]'::jsonb,0,'Art. 32 DFLeg 251/1993 Navarra','Tras tres meses de interinidad ininterrumpida cobra la diferencia, con carácter retroactivo desde el comienzo.',null),
('admin-navarra:17-655f5b48f6','admin-navarra',17,'¿Cómo se proveen en Navarra las vacantes que no son de libre designación?','["Mediante concurso de méritos", "Mediante adscripción provisional", "Mediante concurso-oposición restringido", "Mediante libre designación"]'::jsonb,0,'Art. 33 DFLeg 251/1993 Navarra','Se proveen mediante concurso de méritos entre funcionarios del nivel correspondiente.',null),
('admin-navarra:17-20abc0b444','admin-navarra',17,'¿Con qué periodicidad pueden convocar las Administraciones navarras procesos de movilidad interna?','["Semestral", "Trienal", "Bienal", "Anual"]'::jsonb,2,'Art. 32 bis DFLeg 251/1993 Navarra','Pueden convocar procesos de movilidad interna con periodicidad bienal.',null),
('admin-navarra:17-f72331ac78','admin-navarra',17,'¿En cuántas pagas se abonan las retribuciones anuales de los funcionarios de Navarra?','["Quince, doce ordinarias y tres extraordinarias", "Catorce, doce ordinarias y dos extraordinarias", "Catorce, con extraordinarias en julio y diciembre", "Doce ordinarias, sin pagas extraordinarias"]'::jsonb,1,'Art. 39 DFLeg 251/1993 Navarra','Se abonan en catorce pagas: doce ordinarias y dos extraordinarias, en junio y diciembre.',null),
('admin-navarra:17-bf7628ee67','admin-navarra',17,'¿Cuál de estas es una retribución personal básica de los funcionarios de Navarra?','["El complemento de dedicación exclusiva", "La ayuda familiar", "El complemento de puesto de trabajo", "El premio de antigüedad"]'::jsonb,3,'Art. 40 DFLeg 251/1993 Navarra','Son retribuciones personales básicas el sueldo inicial del nivel, la retribución del grado y el premio de antigüedad.',null),
('admin-navarra:17-5fdf8c747c','admin-navarra',17,'¿Qué índice de proporcionalidad tiene el sueldo inicial del nivel A respecto del nivel E en Navarra?','["1,35", "1,65", "2,5", "2"]'::jsonb,3,'Art. 41 DFLeg 251/1993 Navarra','Los índices son A 2; B 1,65; C 1,35; D 1,15; E 1.',null),
('admin-navarra:17-f35f358e15','admin-navarra',17,'¿Qué índice de proporcionalidad corresponde al nivel C en el Estatuto del Personal de Navarra?','["1,15", "1,35", "1,50", "1,65"]'::jsonb,1,'Art. 41 DFLeg 251/1993 Navarra','El nivel C tiene un índice de proporcionalidad de 1,35 sobre el sueldo inicial del nivel E.',null),
('admin-navarra:17-57ffded28a','admin-navarra',17,'¿En qué consiste la retribución por grado de los funcionarios de Navarra?','["En un porcentaje acumulativo del 9 % del sueldo inicial del nivel", "En un 5 % del sueldo inicial del nivel E por cada grado", "En una cantidad fija anual igual para todos los niveles", "En un porcentaje no acumulativo del 6 % del sueldo inicial del correspondiente nivel"]'::jsonb,0,'Art. 42 DFLeg 251/1993 Navarra','Consiste en un porcentaje acumulativo del 9 % del sueldo inicial del nivel; en el grado 1 no se percibe.',null),
('admin-navarra:17-5e93c543eb','admin-navarra',17,'¿Cada cuánto tiempo se devenga el premio de antigüedad de los funcionarios de Navarra?','["Por trienios vencidos", "Por bienios vencidos", "Por quinquenios vencidos", "Por sexenios vencidos"]'::jsonb,2,'Art. 43 DFLeg 251/1993 Navarra','Consiste en un porcentaje no acumulativo del sueldo inicial del nivel E que se abona por quinquenios vencidos.',null),
('admin-navarra:17-4442e7f0e9','admin-navarra',17,'¿Qué cuantía máxima puede alcanzar el complemento de puesto de trabajo en Navarra?','["El 100 % del sueldo inicial del nivel", "El 35 % del sueldo inicial del nivel", "El 55 % del sueldo inicial del nivel", "El 75 % del sueldo inicial del nivel"]'::jsonb,3,'Art. 44 DFLeg 251/1993 Navarra','No puede exceder del 75 % del sueldo inicial del correspondiente nivel.',null),
('admin-navarra:17-f61a7a4b19','admin-navarra',17,'¿Qué cuantía tiene el complemento de dedicación exclusiva en Navarra?','["El 55 % del sueldo inicial del nivel", "El 35 % del sueldo inicial del nivel", "El 10 % del sueldo inicial del nivel", "El 75 % del sueldo inicial del nivel"]'::jsonb,0,'Art. 45 DFLeg 251/1993 Navarra','La cuantía del complemento de dedicación exclusiva es el 55 % del sueldo inicial del nivel.',null),
('admin-navarra:17-eac0a51505','admin-navarra',17,'¿Qué cuantía tiene el complemento de incompatibilidad en Navarra?','["El 55 % del sueldo inicial del nivel", "El 35 % del sueldo inicial del nivel", "El 25 % del sueldo inicial del nivel", "El 15 % del sueldo inicial del nivel"]'::jsonb,1,'Art. 46 DFLeg 251/1993 Navarra','El complemento de incompatibilidad consiste en un 35 % del sueldo inicial del nivel y no es compatible con el de dedicación exclusiva.',null),
('admin-navarra:17-9875f2cf7a','admin-navarra',17,'¿Puede un funcionario navarro cobrar a la vez los complementos de dedicación exclusiva y de prolongación de jornada?','["Sí, con un límite del 10 %", "Sí, si lo autoriza el Consejero", "No", "Sí, en puestos directivos"]'::jsonb,2,'Art. 47 DFLeg 251/1993 Navarra','Ningún funcionario puede percibir simultáneamente el complemento de prolongación de jornada y el de dedicación exclusiva.',null),
('admin-navarra:17-2b1dd3d5d5','admin-navarra',17,'¿Qué cuantía máxima tiene el complemento de especial riesgo en Navarra?','["El 35 % del sueldo inicial del nivel", "El 15 % del sueldo inicial del nivel", "El 10 % del sueldo inicial del nivel", "El 20 % del sueldo inicial del nivel"]'::jsonb,2,'Art. 48 DFLeg 251/1993 Navarra','No puede exceder del 10 % del sueldo inicial del correspondiente nivel.',null),
('admin-navarra:17-98a2257ffd','admin-navarra',17,'¿Pueden devengar horas extraordinarias los funcionarios navarros con complemento de dedicación exclusiva?','["Solo en días festivos", "No, en ningún caso", "Sí, con autorización previa", "Sí, hasta un máximo anual"]'::jsonb,1,'Art. 51 DFLeg 251/1993 Navarra','En ningún caso pueden devengar horas extraordinarias los funcionarios que perciban el complemento de dedicación exclusiva.',null),
('admin-navarra:17-83292be425','admin-navarra',17,'¿Cuál de estos es un deber de los funcionarios en servicio activo según el Estatuto navarro?','["Sustituir en sus funciones a sus compañeros ausentes, incluidos los superiores", "Informar al superior jerárquico de todas sus actividades privadas, aunque no sean lucrativas", "Afiliarse a una organización sindical", "Residir siempre en la localidad de destino"]'::jsonb,0,'Art. 56 DFLeg 251/1993 Navarra','Entre los deberes figura sustituir en sus funciones a los compañeros ausentes del servicio, incluidos los superiores.',null),
('admin-navarra:17-29d353f462','admin-navarra',17,'¿Qué participación en el capital de una sociedad con conciertos con su Administración es incompatible para un funcionario navarro?','["Superior al 25 %", "Superior al 5 %", "Cualquier participación", "Superior al 10 %"]'::jsonb,3,'Art. 57 DFLeg 251/1993 Navarra','Es absolutamente incompatible la participación superior al 10 % en el capital de sociedades con conciertos con su Administración.',null),
('admin-navarra:17-99459b105e','admin-navarra',17,'¿Qué falta constituye el incumplimiento del régimen de incompatibilidades del Estatuto navarro?','["Leve", "Grave o muy grave según el perjuicio", "Grave", "Muy grave"]'::jsonb,3,'Art. 57 DFLeg 251/1993 Navarra','El incumplimiento del régimen de incompatibilidades constituye falta muy grave.',null),
('admin-navarra:17-164e48c468','admin-navarra',17,'¿Da derecho a compensación la residencia del funcionario navarro en localidad distinta de su destino?','["No implica compensación alguna por el desplazamiento", "Sí, mediante reducción de jornada", "Sí, una indemnización por kilometraje", "Sí, si la distancia supera 30 km"]'::jsonb,0,'Art. 58 DFLeg 251/1993 Navarra','La residencia en otra localidad no exime de la puntualidad ni implica compensación alguna por el desplazamiento.',null),
('admin-navarra:17-a4ad35c974','admin-navarra',17,'¿Cuánto dura el mandato de los Delegados y miembros de las Comisiones de Personal en Navarra?','["Tres años", "Dos años", "Cuatro años", "Cinco años"]'::jsonb,2,'Art. 80 DFLeg 251/1993 Navarra','El mandato es de cuatro años, con posible reelección, y se prorroga si no se promueven nuevas elecciones.',null),
('admin-navarra:17-09db0291cc','admin-navarra',17,'¿Cuántos Delegados de personal se eligen en una Administración navarra con 20 funcionarios?','["Cinco", "Tres", "Uno", "Dos"]'::jsonb,1,'Art. 81 DFLeg 251/1993 Navarra','De 10 a 25 funcionarios se eligen tres Delegados de personal.',null),
('admin-navarra:17-95712d07f1','admin-navarra',17,'¿A partir de cuántos funcionarios se elige una Comisión de Personal en una Administración Pública de Navarra?','["Más de cincuenta", "Más de veinticinco", "Más de doscientos cincuenta", "Más de cien"]'::jsonb,0,'Art. 82 DFLeg 251/1993 Navarra','En las Administraciones con más de cincuenta funcionarios se elige una Comisión de Personal.',null),
('admin-navarra:17-3ab3354770','admin-navarra',17,'¿Cuántas Comisiones de Personal se eligen en la Administración de la Comunidad Foral de Navarra?','["Dos", "Cuatro", "Una", "Seis"]'::jsonb,1,'Art. 82 DFLeg 251/1993 Navarra','Cuatro: docentes no universitarios, Administración de Justicia, Bomberos y Protección Civil, y demás funcionarios.',null),
('admin-navarra:17-374e271394','admin-navarra',17,'¿Qué porcentaje de representantes da presencia a un sindicato en la Mesa general de negociación de Navarra?','["El 5 % o más", "El 15 % o más", "El 25 % o más", "El 10 % o más"]'::jsonb,3,'Art. 83 DFLeg 251/1993 Navarra','Están presentes, además de los más representativos, los sindicatos con el 10 % o más de los representantes.',null),
('admin-navarra:17-8d82f29edd','admin-navarra',17,'¿Cuándo prescriben las faltas leves de los funcionarios de Navarra?','["A los tres meses", "A los seis meses", "Al mes", "Al año"]'::jsonb,2,'Art. 61 DFLeg 251/1993 Navarra','Las faltas leves prescriben al mes; las graves, al año; y las muy graves, a los tres años.',null),
('admin-navarra:17-4b6ef4433f','admin-navarra',17,'¿Cuándo prescriben las faltas graves de los funcionarios de Navarra?','["A los dos años", "A los tres años", "Al año", "A los seis meses"]'::jsonb,2,'Art. 61 DFLeg 251/1993 Navarra','Las faltas graves prescriben al año.',null),
('admin-navarra:17-bf10729530','admin-navarra',17,'¿Cuándo prescriben las faltas muy graves de los funcionarios de Navarra?','["A los seis años", "A los dos años", "A los cuatro años", "A los tres años"]'::jsonb,3,'Art. 61 DFLeg 251/1993 Navarra','Las faltas muy graves prescriben a los tres años.',null),
('admin-navarra:17-7408136110','admin-navarra',17,'¿Qué tipo de falta son trece faltas de puntualidad injustificadas en el mismo mes en Navarra?','["Leve", "Grave", "Muy grave", "No constituye falta"]'::jsonb,1,'Art. 63 DFLeg 251/1993 Navarra','Más de doce faltas de puntualidad injustificadas en el mismo mes son falta grave; hasta doce, leve.',null),
('admin-navarra:17-c505cf3b5e','admin-navarra',17,'¿Qué tipo de falta es una sola falta de asistencia injustificada en un mes en Navarra?','["Leve", "No constituye falta, solo descuento", "Grave", "Muy grave"]'::jsonb,0,'Art. 62 DFLeg 251/1993 Navarra','La falta de asistencia injustificada por una sola vez en un mes es falta leve.',null),
('admin-navarra:17-7a4b0616a7','admin-navarra',17,'¿Qué tipo de falta son seis faltas de asistencia injustificadas en un mes en Navarra?','["Grave si no hay perjuicio", "Muy grave", "Grave", "Leve"]'::jsonb,1,'Art. 64 DFLeg 251/1993 Navarra','Más de cinco faltas de asistencia injustificadas en un mes son falta muy grave.',null),
('admin-navarra:17-78ead6f904','admin-navarra',17,'¿Cómo califica el Estatuto navarro el incumplimiento del deber de secreto profesional?','["Falta leve", "Infracción penal exclusivamente", "Falta muy grave", "Falta grave"]'::jsonb,3,'Art. 63 DFLeg 251/1993 Navarra','El incumplimiento del deber de secreto profesional es falta grave.',null),
('admin-navarra:17-3cfc11e975','admin-navarra',17,'¿Cómo califica el Estatuto navarro la intervención en un procedimiento cuando concurre causa de abstención?','["No es falta, solo causa de nulidad", "Falta muy grave", "Falta grave", "Falta leve"]'::jsonb,2,'Art. 63 DFLeg 251/1993 Navarra','La intervención en un procedimiento concurriendo causa legal de abstención es falta grave.',null),
('admin-navarra:17-53aa16306f','admin-navarra',17,'¿Qué se entiende por abandono del servicio a efectos disciplinarios en Navarra?','["La ausencia continuada e injustificada durante más de un mes", "La ausencia injustificada durante más de quince días", "La ausencia injustificada durante más de cinco días en un mes", "La ausencia continuada durante más de tres meses"]'::jsonb,0,'Art. 64 DFLeg 251/1993 Navarra','Es falta muy grave el abandono del servicio: ausencia continuada e injustificada durante más de un mes.',null),
('admin-navarra:17-5956dbb0eb','admin-navarra',17,'¿Cuál de estas conductas es falta muy grave según el Estatuto navarro?','["La incorrección en el trato con los compañeros", "Originar altercados en el trabajo", "El descuido en la conservación del material", "El acoso sexual"]'::jsonb,3,'Art. 64 DFLeg 251/1993 Navarra','El acoso sexual es falta muy grave; los altercados son graves y el descuido o la incorrección, leves.',null),
('admin-navarra:17-cb5eb35a66','admin-navarra',17,'Según el Estatuto navarro, ¿cuándo existe reiteración?','["Cuando se ha sido sancionado antes por otra u otras faltas de la misma índole", "Cuando la sanción anterior no se ha cumplido", "Cuando se ha sido sancionado por una falta más grave o por dos de igual o menor gravedad", "Cuando se cometen dos faltas en el mismo mes"]'::jsonb,2,'Art. 65 DFLeg 251/1993 Navarra','Hay reiteración si se fue sancionado por otra falta de mayor gravedad o por dos de gravedad igual o inferior; reincidencia, por faltas de la misma índole.',null),
('admin-navarra:17-712172d11a','admin-navarra',17,'Además de los autores, ¿quién incurre en responsabilidad disciplinaria según el Estatuto navarro?','["Los superiores que toleren las faltas y quienes las encubran o induzcan", "Solo los autores materiales", "Los compañeros que estén presentes", "Los representantes sindicales del centro"]'::jsonb,0,'Art. 66 DFLeg 251/1993 Navarra','Incurren también los superiores que las toleren, los que las encubran y los que induzcan a su comisión.',null),
('admin-navarra:17-f6f5acc68f','admin-navarra',17,'¿Qué sanción puede imponerse por falta leve según el Estatuto navarro?','["Suspensión de funciones hasta un año", "Suspensión de empleo y sueldo de uno a cuatro días", "Suspensión de empleo y sueldo de cinco a treinta días", "Traslado forzoso sin cambio de residencia"]'::jsonb,1,'Art. 67 DFLeg 251/1993 Navarra','Las faltas leves se sancionan con apercibimiento o suspensión de empleo y sueldo de uno a cuatro días.',null),
('admin-navarra:17-f2a986c4d7','admin-navarra',17,'¿Qué sanción puede imponerse por falta grave según el Estatuto navarro?','["Apercibimiento", "Separación del servicio", "Suspensión de funciones de uno a cinco años", "Traslado forzoso con o sin cambio de residencia"]'::jsonb,3,'Art. 67 DFLeg 251/1993 Navarra','Las graves: suspensión de empleo y sueldo de cinco a treinta días, traslado forzoso o suspensión de funciones hasta un año.',null),
('admin-navarra:17-fc2f6db372','admin-navarra',17,'¿Qué sanciones corresponden a las faltas muy graves en el Estatuto navarro?','["Suspensión de funciones hasta un año, traslado forzoso o suspensión de empleo y sueldo", "Suspensión de funciones de uno a cinco años o separación del servicio", "Separación del servicio exclusivamente", "Suspensión de empleo y sueldo hasta seis meses"]'::jsonb,1,'Art. 67 DFLeg 251/1993 Navarra','Las muy graves se sancionan con suspensión de funciones de uno a cinco años o separación del servicio.',null),
('admin-navarra:17-257777c0a1','admin-navarra',17,'¿En qué plazo pueden cancelarse las anotaciones de sanciones por faltas graves en Navarra?','["Dos años desde el cumplimiento de la sanción", "Seis meses desde el cumplimiento de la sanción", "Un año desde la imposición de la sanción", "Seis años desde el cumplimiento de la sanción"]'::jsonb,0,'Art. 69 DFLeg 251/1993 Navarra','Seis meses para las leves, dos años para las graves y seis años para las muy graves, desde el cumplimiento.',null),
('admin-navarra:17-222639251d','admin-navarra',17,'¿Se cancela la anotación de la sanción de separación definitiva del servicio en Navarra?','["Sí, a los seis años", "Sí, a los diez años", "No, nunca", "Sí, a instancia del interesado en cualquier momento"]'::jsonb,2,'Art. 69 DFLeg 251/1993 Navarra','La anotación de la sanción de separación definitiva del servicio no es objeto de cancelación.',null),
('admin-navarra:17-530fff7ca9','admin-navarra',17,'¿Quién impone las sanciones por faltas leves en el Estatuto navarro?','["El superior jerárquico, previo expediente sumario con audiencia", "La Comisión de Personal", "El Consejero competente, previo expediente disciplinario con audiencia del interesado", "El Gobierno de Navarra"]'::jsonb,0,'Art. 70 DFLeg 251/1993 Navarra','Las impone el superior jerárquico, previa incoación de un expediente sumario que garantice la audiencia del interesado.',null),
('admin-navarra:17-c6f6262272','admin-navarra',17,'¿Cuándo prescriben las sanciones impuestas por faltas graves en Navarra?','["A los tres años", "A los seis meses", "Al año", "A los dos años"]'::jsonb,3,'Art. 70 DFLeg 251/1993 Navarra','Las sanciones por faltas leves prescriben al año; por graves, a los dos años; por muy graves, a los tres años.',null),
('admin-navarra:17-cd01651781','admin-navarra',17,'¿Cuál es el plazo máximo para resolver y notificar un procedimiento disciplinario por falta grave en Navarra?','["Dieciocho meses desde los hechos", "Tres meses desde la incoación", "Doce meses desde la incoación", "Seis meses desde la incoación"]'::jsonb,2,'Art. 71 DFLeg 251/1993 Navarra','Es de doce meses desde la resolución de incoación para faltas graves y muy graves, y de seis meses para las leves.',null),
('admin-navarra:18-c04dcb7f89','admin-navarra',18,'La Ley Orgánica 3/2007 tiene por objeto:','["Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres", "Establecer medidas de protección integral contra la violencia de género y de igualdad de oportunidades en el empleo", "Hacer efectivo el derecho de igualdad de trato entre mujeres y hombres, pero solo en el ámbito del empleo público y de la negociación colectiva", "Regular la igualdad de trato y la no discriminación por cualquier circunstancia personal"]'::jsonb,0,'Art. 1.1 LO 3/2007','Su objeto es hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres.',null),
('admin-navarra:18-7953aea261','admin-navarra',18,'El principio de igualdad de trato entre mujeres y hombres supone:','["La igualdad en el ámbito laboral y en el acceso al empleo", "La ausencia de toda discriminación, directa o indirecta, por razón de sexo", "La ausencia de discriminación directa por razón de sexo, pero no de la indirecta, que se rige por la normativa laboral", "La paridad obligatoria en todos los órganos públicos y privados, con independencia de su composición"]'::jsonb,1,'Art. 3 LO 3/2007','Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, especialmente por maternidad, obligaciones familiares y estado civil.',null),
('admin-navarra:18-9428a36646','admin-navarra',18,'Se considera discriminación directa por razón de sexo la situación en que una persona:','["Recibe una medida de acción positiva destinada a corregir situaciones de desigualdad", "Es tratada igual que otra persona en una situación distinta", "Es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable", "Sufre una desventaja particular respecto de personas del otro sexo por una disposición, criterio o práctica aparentemente neutros"]'::jsonb,2,'Art. 6.1 LO 3/2007','Es la situación de quien es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable. El trato por disposición aparentemente neutra es la discriminación indirecta.',null),
('admin-navarra:18-4ce1a492dd','admin-navarra',18,'El acoso sexual es cualquier comportamiento, verbal o físico, de naturaleza sexual que:','["Se produzca fuera del lugar de trabajo", "Se repita al menos tres veces y lo denuncie la persona afectada o un tercero", "Produzca una lesión física acreditada", "Tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona"]'::jsonb,3,'Art. 7.1 LO 3/2007','Tiene el propósito o produce el efecto de atentar contra la dignidad de una persona, en particular cuando crea un entorno intimidatorio, degradante u ofensivo.',null),
('admin-navarra:18-6464723998','admin-navarra',18,'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:','["Discriminación directa por razón de sexo", "Discriminación indirecta por razón de sexo, salvo que la empresa acredite una justificación objetiva", "Acoso por razón de sexo", "Una infracción laboral leve"]'::jsonb,0,'Art. 8 LO 3/2007','Constituye discriminación directa por razón de sexo.',null),
('admin-navarra:18-d918b46692','admin-navarra',18,'Según la LO 3/2007, el principio de igualdad de trato y oportunidades informará la actuación de todos los Poderes Públicos con carácter:','["Excepcional", "Transversal", "Subsidiario", "Voluntario"]'::jsonb,1,'Art. 15 LO 3/2007','Informará, con carácter transversal, la actuación de todos los Poderes Públicos.',null),
('admin-navarra:18-01e4fd5103','admin-navarra',18,'¿Qué empresas deben elaborar y aplicar un plan de igualdad?','["Todas, cualquiera que sea su plantilla", "Las de más de 250 trabajadores", "Las de cincuenta o más trabajadores", "Solo las empresas públicas y las que contraten con la Administración, cualquiera que sea su plantilla"]'::jsonb,2,'Art. 45.2 LO 3/2007','Las empresas de cincuenta o más trabajadores.',null),
('admin-navarra:18-6063d28270','admin-navarra',18,'Según la LO 3/2007, hay composición equilibrada cuando las personas de cada sexo:','["Son exactamente el 50 %", "No superan el 70 % ni son menos del 30 %", "No superan el 55 % ni son menos del 45 %", "No superan el 60 % ni son menos del 40 %"]'::jsonb,3,'Disp. adicional 1.ª LO 3/2007','Las personas de cada sexo no superan el sesenta por ciento ni son menos del cuarenta por ciento.',null),
('admin-navarra:18-f112b29b48','admin-navarra',18,'El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado se aprueba por el Gobierno:','["Cada diez años", "Cada año", "Solo cuando lo pide el Congreso", "Al inicio de cada legislatura"]'::jsonb,3,'Art. 64 LO 3/2007','Su cumplimiento se evalúa anualmente por el Consejo de Ministros.',null),
('admin-navarra:18-ef967f04b0','admin-navarra',18,'En los litigios sobre acoso sexual y acoso por razón de sexo, está legitimada:','["Cualquier ciudadano", "Únicamente la persona acosada", "El sindicato mayoritario en todo caso", "El Ministerio Fiscal en exclusiva"]'::jsonb,1,'Art. 12.3 LO 3/2007','La persona acosada es la única legitimada.',null),
('admin-navarra:18-72f1ed5212','admin-navarra',18,'Según el art. 6.3 de la LO 3/2007, toda orden de discriminar, directa o indirectamente, por razón de sexo:','["Se considerará en todo caso discriminatoria", "No tiene relevancia jurídica si no llega a ejecutarse", "Solo es discriminatoria si se ejecuta", "Es válida si procede de un superior"]'::jsonb,0,'Art. 6.3 LO 3/2007','La orden de discriminar es en sí misma discriminación.',null),
('admin-navarra:18-3c10ff739b','admin-navarra',18,'Las acciones positivas para hacer efectivo el derecho a la igualdad pueden adoptarlas:','["Solo el Gobierno y las Administraciones públicas", "Solo los jueces y tribunales en sus sentencias", "Solo las empresas de más de 250 trabajadores, dentro de su plan de igualdad negociado con la representación legal de los trabajadores", "Los poderes públicos y también las personas físicas y jurídicas privadas"]'::jsonb,3,'Art. 11 LO 3/2007','Deben ser razonables y proporcionadas.',null),
('admin-navarra:18-a6d835fc88','admin-navarra',18,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe del Consejo de Estado en todo caso", "Un informe sobre su impacto por razón de género", "Un informe económico de la UE", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('admin-navarra:18-72fca32297','admin-navarra',18,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su afiliación a un partido político o a un sindicato", "Su cambio de domicilio", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('admin-navarra:18-40c069cb77','admin-navarra',18,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración", "Suprimir los planes de igualdad", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Reservar los puestos directivos a la persona más antigua"]'::jsonb,0,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('admin-navarra:18-5ac814b6b0','admin-navarra',18,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El Ministerio Fiscal", "La persona demandada", "El juez"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.',null),
('admin-navarra:18-b9edec85d9','admin-navarra',18,'Según la Ley Foral 17/2019, ¿qué es la brecha de género?','["La concentración de mujeres en un número reducido de profesiones", "La diferencia entre las tasas masculina y femenina que refleja la desigual distribución de recursos, acceso y poder", "La diferencia salarial media entre hombres y mujeres en un mismo puesto", "La situación de una mujer que sufre varias discriminaciones a la vez"]'::jsonb,1,'Art. 3 LF 17/2019 Navarra','La brecha de género es la diferencia entre las tasas masculina y femenina que pone de manifiesto la desigual distribución de recursos, acceso y poder.',null),
('admin-navarra:18-353d8cac47','admin-navarra',18,'¿Cómo define la Ley Foral 17/2019 la segregación ocupacional vertical?','["La distinta distribución del uso del tiempo", "Las desigualdades en el acceso a categorías directivas y cargos con poder de decisión", "La diferente elección de estudios por razón de sexo", "La concentración en un abanico restringido de profesiones"]'::jsonb,1,'Art. 3 LF 17/2019 Navarra','Es vertical cuando hay desigualdades en el acceso a categorías directivas y cargos con poder de decisión; horizontal, cuando hay concentración en pocas profesiones.',null),
('admin-navarra:18-b3dc50a1a3','admin-navarra',18,'Según el principio de representación equilibrada de la Ley Foral 17/2019, ¿qué porcentaje no debe superar ningún sexo?','["El 60 %", "El 65 %", "El 70 %", "El 50 %"]'::jsonb,0,'Art. 4 LF 17/2019 Navarra','Ningún sexo superará el 60 % ni será inferior al 40 %, y se tenderá al 50 % de cada sexo.',null),
('admin-navarra:18-68e5744ff7','admin-navarra',18,'¿Qué consideración tienen las asociaciones para la promoción de la igualdad ante las Administraciones navarras?','["Órganos consultivos obligatorios", "Entidades colaboradoras de la Administración", "Personas interesadas como titulares de intereses legítimos colectivos", "Corporaciones de derecho público"]'::jsonb,2,'Art. 5 LF 17/2019 Navarra','Se consideran personas interesadas, titulares de intereses legítimos colectivos, a efectos del art. 4 de la Ley 39/2015.',null),
('admin-navarra:18-71d668608f','admin-navarra',18,'¿A qué Departamento atribuye la Ley Foral 17/2019 la competencia en políticas de igualdad?','["Al de Derechos Sociales", "Al de Educación", "Al de Economía y Hacienda", "Al de Presidencia, o al que figure en primer lugar en el decreto de estructura"]'::jsonb,3,'Art. 7 LF 17/2019 Navarra','Corresponde al Departamento de Presidencia o al que figure en primer lugar en el orden de prelación de la estructura básica.',null),
('admin-navarra:18-ee73ac7259','admin-navarra',18,'¿Qué naturaleza tiene el Instituto Navarro para la Igualdad según la Ley Foral 17/2019?','["Servicio integrado en un Departamento", "Órgano colegiado consultivo", "Sociedad pública de la Comunidad Foral", "Organismo autónomo con rango de Dirección General"]'::jsonb,3,'Art. 8 LF 17/2019 Navarra','Es un organismo autónomo con rango de Dirección General y funciones exclusivamente en igualdad de género.',null),
('admin-navarra:18-bddfc4f405','admin-navarra',18,'¿Quién elabora el Plan Estratégico para la Igualdad de Navarra?','["El Instituto Navarro para la Igualdad", "La Comisión Interdepartamental para la Igualdad", "El Parlamento de Navarra", "El Consejo Navarro de Igualdad"]'::jsonb,0,'Art. 8 LF 17/2019 Navarra','Le corresponde al Instituto Navarro para la Igualdad elaborar el Plan Estratégico, que informa el Consejo y aprueba el Gobierno.',null),
('admin-navarra:18-fd78f30e38','admin-navarra',18,'¿Qué debe existir, al menos, en cada Departamento de la Administración foral y sus organismos autónomos según la Ley Foral 17/2019?','["Un plan de igualdad propio aprobado por ley", "Una Unidad de Igualdad", "Una comisión paritaria de igualdad", "Una persona delegada del Consejo Navarro de Igualdad"]'::jsonb,1,'Art. 9 LF 17/2019 Navarra','En cada Departamento y organismo autónomo ejercerá su función, al menos, una Unidad de Igualdad.',null),
('admin-navarra:18-bf5384c411','admin-navarra',18,'¿A qué organismo figura adscrito el personal técnico de las Unidades de Igualdad?','["A la Dirección General de Función Pública", "Al Consejo Navarro de Igualdad", "Al Instituto Navarro para la Igualdad", "Al Departamento en el que trabaja"]'::jsonb,2,'Art. 9 LF 17/2019 Navarra','Ese personal técnico, a tiempo completo, figura adscrito al Instituto Navarro para la Igualdad.',null),
('admin-navarra:18-3c3058bfce','admin-navarra',18,'¿Qué es el Consejo Navarro de Igualdad según la Ley Foral 17/2019?','["El órgano de coordinación entre Departamentos", "El órgano consultivo y de participación superior en materia de igualdad", "El órgano sancionador en materia de igualdad", "El organismo autónomo que gestiona las políticas de igualdad"]'::jsonb,1,'Art. 10 LF 17/2019 Navarra','Es el órgano consultivo y de participación superior en la Comunidad Foral en materia de igualdad entre mujeres y hombres.',null),
('admin-navarra:18-7ce5657896','admin-navarra',18,'¿Quién preside la Comisión Interdepartamental para la Igualdad de Navarra?','["El Consejero de Derechos Sociales", "La Directora Gerente del Instituto Navarro para la Igualdad", "La persona que ostente la Presidencia del Gobierno de Navarra", "La persona titular del Departamento de Presidencia"]'::jsonb,2,'Art. 11 LF 17/2019 Navarra','Está presidida por quien ostente la Presidencia del Gobierno de Navarra y la integran directores generales de los Departamentos.',null),
('admin-navarra:18-97e2f59928','admin-navarra',18,'¿Con qué frecuencia mínima debe convocarse la Comisión Interdepartamental para la Igualdad, además de para conocer el Plan Estratégico?','["Una vez al trimestre", "Una vez cada dos años", "Dos veces al año", "Una vez al año"]'::jsonb,3,'Art. 11 LF 17/2019 Navarra','La presidencia la convocará, al menos, una vez al año.',null),
('admin-navarra:18-c8eabd8e45','admin-navarra',18,'¿Quién ejerce la potestad sancionadora prevista en la Ley Foral 17/2019?','["La persona titular del Departamento de Presidencia", "El Consejo Navarro de Igualdad", "El Gobierno de Navarra en pleno", "El Instituto Navarro para la Igualdad"]'::jsonb,0,'Art. 7 LF 17/2019 Navarra','Entre las funciones del titular del Departamento de Presidencia está ejercer la potestad sancionadora que le atribuye la ley foral.',null),
('admin-navarra:19-a8021c997c','admin-navarra',19,'Según la Ley Foral 5/2018, ¿qué debe acreditar quien solicita información pública?','["Un interés legítimo y directo en la información, o la condición de interesado en el procedimiento", "Nada: no es necesario motivar la solicitud ni acreditar interés alguno", "La finalidad para la que va a usar la información", "Su condición de vecino de Navarra"]'::jsonb,1,'Art. 30 LF 5/2018 Navarra','No es necesario motivar la solicitud ni invocar la ley foral, ni acreditar interés alguno.',null),
('admin-navarra:19-ff73e5ea12','admin-navarra',19,'¿Cómo deben interpretarse las limitaciones al derecho de acceso a la información pública en la Ley Foral 5/2018?','["De manera amplia, en favor de la reserva", "Según el criterio discrecional del órgano", "De manera restrictiva y justificada, atendiendo al caso concreto", "Siempre a favor del tercero afectado"]'::jsonb,2,'Art. 31 LF 5/2018 Navarra','Deben interpretarse de manera restrictiva y justificada, atendiendo a la concurrencia de un interés público superior.',null),
('admin-navarra:19-71f2d620bd','admin-navarra',19,'¿Qué se exige para dar acceso a información con categorías especiales de datos personales según la Ley Foral 5/2018?','["Una ponderación razonada del interés público frente al derecho a la protección de datos", "Que la información tenga más de cinco años", "Informe favorable del Consejo de Transparencia", "Consentimiento expreso y por escrito del afectado, o una norma con rango de ley"]'::jsonb,3,'Art. 32 LF 5/2018 Navarra','Solo se autoriza con consentimiento expreso y por escrito del afectado o si lo ampara una norma con rango de ley.',null),
('admin-navarra:19-e7618b6f51','admin-navarra',19,'Si la información está afectada solo en parte por un límite, ¿qué prevé la Ley Foral 5/2018?','["Conceder el acceso parcial a la información no afectada", "Denegar la totalidad de la solicitud", "Suspender el procedimiento hasta que cese el límite que afecta a parte de la información", "Remitir la solicitud al Consejo de Transparencia"]'::jsonb,0,'Art. 33 LF 5/2018 Navarra','Se concede el acceso parcial a la información no afectada, con advertencia de la reserva.',null),
('admin-navarra:19-a93e408b86','admin-navarra',19,'¿Es necesario acreditar la identidad del solicitante de información pública en Navarra?','["Sí, mediante firma electrónica cualificada o, en papel, con copia del documento de identidad", "No, basta con que conste la identidad sin necesidad de acreditarla", "Sí, con DNI o certificado electrónico", "Solo si la solicitud se presenta presencialmente"]'::jsonb,1,'Art. 34 LF 5/2018 Navarra','La solicitud debe permitir la constancia de la identidad del solicitante sin que resulte necesaria su acreditación.',null),
('admin-navarra:19-6d04c42ee3','admin-navarra',19,'¿Qué plazo se da al solicitante para concretar una solicitud de información imprecisa según la Ley Foral 5/2018?','["Un mes", "Quince días naturales", "Diez días hábiles", "Cinco días hábiles"]'::jsonb,2,'Art. 35 LF 5/2018 Navarra','Se le pide que la concrete en diez días hábiles, con suspensión del plazo para resolver, pudiendo tenerlo por desistido.',null),
('admin-navarra:19-389b80be1a','admin-navarra',19,'¿Cuál de estas es causa de inadmisión de una solicitud de información en la Ley Foral 5/2018?','["Pedir la elaboración de un informe o dictamen", "Presentar la solicitud en vascuence", "No motivar la solicitud", "Solicitar información sobre contratos públicos"]'::jsonb,0,'Art. 37 LF 5/2018 Navarra','Se inadmiten las peticiones de respuesta a consultas jurídicas o de elaboración de informes o dictámenes.',null),
('admin-navarra:19-91edeb473c','admin-navarra',19,'¿Puede inadmitirse por reelaboración la información obtenible mediante un tratamiento informatizado de uso corriente?','["Sí, si requiere más de un día de trabajo", "Sí, si la información está en varios documentos", "Sí, siempre", "No"]'::jsonb,3,'Art. 37 LF 5/2018 Navarra','No se considera reelaboración la que pueda obtenerse con tratamiento informatizado corriente ni la de aglutinar información dispersa.',null),
('admin-navarra:19-6c27430a0b','admin-navarra',19,'¿En qué plazo debe derivarse una solicitud dirigida a un órgano que no dispone de la información?','["Diez días naturales", "Un mes", "Quince días hábiles", "Cinco días hábiles"]'::jsonb,0,'Art. 38 LF 5/2018 Navarra','Debe derivarla al órgano que disponga de ella en un plazo de diez días naturales, comunicándolo al solicitante.',null),
('admin-navarra:19-6d6cecdf8a','admin-navarra',19,'¿Qué plazo de audiencia se da a los terceros afectados por una solicitud de acceso según la Ley Foral 5/2018?','["Cinco días", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 39 LF 5/2018 Navarra','En los supuestos de terceros afectados y del art. 32, la audiencia se otorga por un plazo de 15 días.',null),
('admin-navarra:19-df8b763a18','admin-navarra',19,'¿Cuál es el plazo general para resolver una solicitud de acceso a la información pública en Navarra?','["Tres meses", "Quince días hábiles, ampliables por un mes", "Un mes, ampliable por otro mes", "Veinte días hábiles, ampliables por otros veinte"]'::jsonb,2,'Art. 41 LF 5/2018 Navarra','Un mes desde la entrada en el registro, ampliable por otro mes si el volumen y la complejidad lo exigen.',null),
('admin-navarra:19-04ed9f0c28','admin-navarra',19,'¿Qué efecto tiene el silencio en las solicitudes de acceso a la información pública según la Ley Foral 5/2018?','["Desestimatorio en todo caso", "Estimatorio, salvo denegación impuesta por norma con rango de ley", "Estimatorio solo para personas físicas", "Desestimatorio si hay terceros afectados"]'::jsonb,1,'Art. 41 LF 5/2018 Navarra','Si no hay resolución expresa en plazo, se entiende estimada la solicitud, salvo denegación impuesta por norma con rango de ley.',null),
('admin-navarra:19-b7366bbeba','admin-navarra',19,'¿Agotan la vía administrativa las resoluciones en materia de acceso a la información pública en Navarra?','["Solo las del Gobierno de Navarra", "No, cabe recurso obligatorio ante el Consejo de Transparencia de Navarra", "Sí, y son recurribles ante la jurisdicción contencioso-administrativa", "No, cabe recurso de alzada"]'::jsonb,2,'Art. 42 LF 5/2018 Navarra','Ponen fin a la vía administrativa, sin perjuicio de la reclamación potestativa del art. 45.',null),
('admin-navarra:19-c8296ab1b1','admin-navarra',19,'¿Cuál de estos accesos a la información pública es gratuito según la Ley Foral 5/2018?','["La copia certificada de documentos", "La entrega de información por correo electrónico", "La expedición de copias en papel", "La transposición a otros formatos"]'::jsonb,1,'Art. 44 LF 5/2018 Navarra','Son gratuitos, entre otros, el examen in situ y la entrega por correo electrónico; las copias pueden costar hasta su coste.',null),
('admin-navarra:19-3c5d351763','admin-navarra',19,'¿Qué carácter tiene la reclamación ante el Consejo de Transparencia de Navarra?','["Potestativo, posterior a la sentencia", "Obligatorio antes de acudir a los tribunales", "Obligatorio solo frente al silencio", "Potestativo, previo a la vía contencioso-administrativa"]'::jsonb,3,'Art. 45 LF 5/2018 Navarra','Las resoluciones en materia de acceso pueden ser objeto de reclamación potestativa ante el Consejo de Transparencia.',null),
('admin-navarra:19-908f14e53a','admin-navarra',19,'¿En qué plazo se interpone la reclamación ante el Consejo de Transparencia de Navarra frente a una resolución expresa?','["Un mes desde el día siguiente a la notificación", "Quince días hábiles desde la notificación", "Tres meses desde la notificación", "Dos meses desde la notificación"]'::jsonb,0,'Art. 45 LF 5/2018 Navarra','Se interpone en el plazo de un mes desde la notificación, o en cualquier momento frente al silencio.',null),
('admin-navarra:19-4cb6ca5c30','admin-navarra',19,'¿Qué plazo tiene el Consejo de Transparencia de Navarra para resolver una reclamación y qué efecto tiene el silencio?','["Tres meses; se entiende estimada", "Un mes; se entiende estimada", "Dos meses; se entiende desestimada", "Tres meses; se entiende desestimada"]'::jsonb,3,'Art. 45 LF 5/2018 Navarra','El plazo máximo es de tres meses, transcurrido el cual la reclamación se entiende desestimada.',null),
('admin-navarra:19-3a3d3c4e10','admin-navarra',19,'¿En qué entidades locales navarras se creará un registro público de grupos de interés?','["En todas las entidades locales", "Solo en Pamplona", "En las de población superior a 5.000 habitantes", "En las de población superior a 20.000 habitantes"]'::jsonb,2,'Art. 47 LF 5/2018 Navarra','Se crea en la Comunidad Foral y en las entidades locales con población superior a 5.000 habitantes.',null),
('admin-navarra:20-532f74a74e','admin-navarra',20,'¿A través de qué órgano ejerce el Departamento de Economía y Hacienda el control interno en la Administración de la Comunidad Foral?','["La Intervención General", "La Cámara de Comptos", "La Dirección General del Presupuesto", "El Tribunal de Cuentas"]'::jsonb,0,'Art. 94 LF 13/2007 Navarra','El control interno corre a cargo del Departamento de Economía y Hacienda, a través de la Intervención General.',null),
('admin-navarra:20-4e777b99d2','admin-navarra',20,'¿Mediante qué modalidades se realiza el control interno según la Ley Foral 13/2007?','["Control de legalidad, control de oportunidad y control contable", "Función interventora, control financiero permanente y auditoría pública", "Intervención formal, intervención material y control de eficacia", "Fiscalización previa, control parlamentario y auditoría externa"]'::jsonb,1,'Art. 93 LF 13/2007 Navarra','El control se realiza mediante la función interventora, el control financiero permanente y la auditoría pública.',null),
('admin-navarra:20-b5c8a738d0','admin-navarra',20,'¿Con qué principios se ejercen las funciones de control interno en la Hacienda Pública de Navarra?','["Dependencia del órgano controlado y oportunidad", "Unidad de caja, especialidad y anualidad", "Autonomía, ejercicio desconcentrado y jerarquía interna", "Publicidad, concurrencia y discrecionalidad"]'::jsonb,2,'Art. 95 LF 13/2007 Navarra','Se ejercen conforme a los principios de autonomía, ejercicio desconcentrado y jerarquía interna.',null),
('admin-navarra:20-e37ce31e9f','admin-navarra',20,'¿Qué tiene por objeto la función interventora según la Ley Foral 13/2007?','["Controlar los actos que reconocen derechos o realizan gastos antes de que se aprueben", "Auditar las cuentas una vez cerrado el ejercicio", "Enjuiciar la responsabilidad contable de los gestores", "Elaborar el anteproyecto de presupuestos"]'::jsonb,0,'Art. 97 LF 13/2007 Navarra','Tiene por objeto controlar, antes de su aprobación, los actos que den lugar al reconocimiento de derechos o a la realización de gastos.',null),
('admin-navarra:20-b5a08de546','admin-navarra',20,'¿En qué consiste la intervención material en la Hacienda Pública de Navarra?','["En examinar los documentos que deben constar en el expediente", "En verificar la contabilización de las operaciones", "En informar el anteproyecto de presupuestos", "En comprobar la real y efectiva aplicación de los fondos públicos"]'::jsonb,3,'Art. 100 LF 13/2007 Navarra','En la intervención material se comprueba la real y efectiva aplicación de los fondos públicos; la formal verifica los requisitos documentales.',null),
('admin-navarra:20-e245190a85','admin-navarra',20,'¿A qué control quedan sometidos los actos excluidos de intervención previa en Navarra?','["A ningún control posterior", "Al control financiero permanente", "Al control parlamentario directo", "A la auditoría de la Cámara de Comptos exclusivamente"]'::jsonb,1,'Art. 98 LF 13/2007 Navarra','Los actos sometidos a intervención limitada o excluidos de intervención previa quedan sometidos a control financiero permanente.',null),
('admin-navarra:20-ce0ac995de','admin-navarra',20,'¿Qué grado de culpa exige la responsabilidad de autoridades y funcionarios frente a la Hacienda Pública de Navarra?','["Solo dolo", "Dolo o culpa grave", "Cualquier grado de culpa", "Responsabilidad objetiva, sin culpa"]'::jsonb,1,'Art. 131 LF 13/2007 Navarra','Quienes por dolo o culpa grave realicen las acciones u omisiones previstas deben indemnizar a la Hacienda Pública de Navarra.',null),
('admin-navarra:20-45c9c7e7c0','admin-navarra',20,'Cuando concurren varios responsables sin dolo ante la Hacienda Pública de Navarra, ¿cómo responden?','["Mancomunadamente, por iguales partes", "Solidariamente en todo caso", "Solo responde el de mayor rango", "Proporcionalmente a sus retribuciones"]'::jsonb,0,'Art. 133 LF 13/2007 Navarra','La responsabilidad es mancomunada por iguales partes, salvo dolo, en que es solidaria.',null),
('admin-navarra:20-0c318ca645','admin-navarra',20,'¿Quién incoa y resuelve, como regla general, el expediente de responsabilidad frente a la Hacienda Pública de Navarra?','["La Cámara de Comptos", "El Parlamento de Navarra", "El Gobierno de Navarra en todo caso", "El Consejero de Economía y Hacienda"]'::jsonb,3,'Art. 134 LF 13/2007 Navarra','Salvo los supuestos atribuidos al Consejero Secretario, al Presidente o al Gobierno, corresponde al Consejero de Economía y Hacienda.',null),
('admin-navarra:20-89443d2ca3','admin-navarra',20,'¿Quién incoa el expediente de responsabilidad cuando se exige al Presidente del Gobierno de Navarra?','["El Presidente del Parlamento de Navarra", "El Gobierno de Navarra", "El Consejero Secretario del Gobierno de Navarra", "El Consejero de Economía y Hacienda"]'::jsonb,2,'Art. 134 LF 13/2007 Navarra','Cuando se trata de exigir responsabilidad al Presidente, la competencia corresponde al Consejero Secretario del Gobierno.',null),
('admin-navarra:20-981ac20723','admin-navarra',20,'¿Cuál de estos forma parte del sector público foral según la Ley Foral 13/2007 de la Hacienda Pública de Navarra?','["El Consejo de Navarra", "La Delegación del Gobierno en Navarra", "Los colegios profesionales de Navarra", "Las entidades locales de Navarra"]'::jsonb,0,'Art. 2 LF 13/2007 Navarra','Forman parte, entre otros, la Administración foral y sus organismos autónomos, el Parlamento, el Consejo de Navarra y las empresas, sociedades y fundaciones públicas.',null),
('admin-navarra:20-7b22b5087e','admin-navarra',20,'¿Qué Derecho tiene preferencia como supletorio en el régimen económico-financiero foral, en defecto del administrativo?','["El Código Civil estatal", "La legislación tributaria estatal", "El Derecho mercantil", "El Derecho civil foral navarro"]'::jsonb,3,'Art. 3 LF 13/2007 Navarra','Son supletorias las normas de Derecho Administrativo y, en su defecto, las de Derecho Común, con preferencia del Derecho civil foral navarro.',null),
('admin-navarra:20-ff132245bf','admin-navarra',20,'¿Cuál de estas materias debe regularse por ley foral según la Ley Foral 13/2007?','["La estructura de los Departamentos", "El calendario de pagos de la Tesorería", "Los límites de las operaciones de endeudamiento y de constitución de avales", "Las instrucciones de cierre del ejercicio"]'::jsonb,2,'Art. 4 LF 13/2007 Navarra','Se regulan por ley foral, entre otras, los presupuestos, los tributos y los límites de endeudamiento y avales.',null),
('admin-navarra:20-c5f7bd024e','admin-navarra',20,'¿Qué comprende la Hacienda Pública de Navarra según la Ley Foral 13/2007?','["Solo los tributos propios de la Comunidad Foral y los procedentes del Convenio Económico", "Los derechos y obligaciones económicos de la Administración foral y sus organismos públicos", "Los ingresos procedentes del Convenio Económico", "Los bienes de dominio público de Navarra"]'::jsonb,1,'Art. 7 LF 13/2007 Navarra','Comprende el conjunto de derechos y obligaciones de contenido económico de la Administración foral o de sus organismos públicos.',null),
('admin-navarra:20-43ad9f06c9','admin-navarra',20,'¿Quién autoriza transigir judicialmente sobre derechos económicos de la Hacienda Pública de Navarra?','["El Consejero de Economía y Hacienda por sí solo", "El Director General del Presupuesto", "El Parlamento de Navarra, mediante ley foral aprobada a propuesta del Gobierno", "El Gobierno de Navarra, a propuesta del Consejero de Economía y Hacienda"]'::jsonb,3,'Art. 9 LF 13/2007 Navarra','Solo cabe transigir o someter a arbitraje mediante Acuerdo del Gobierno, a propuesta del Consejero de Economía y Hacienda.',null),
('admin-navarra:20-7184a53c23','admin-navarra',20,'Si un deudor paga sin indicar a qué deuda imputa el pago, ¿a qué deuda se aplica según la Ley Foral 13/2007?','["A la más onerosa y, en su defecto, a la más antigua", "A la de menor importe", "A la más antigua y, en su defecto, a la de mayor importe", "A la que elija la Administración libremente"]'::jsonb,0,'Art. 10 LF 13/2007 Navarra','Se aplica a la deuda más onerosa para el deudor y, en su defecto, a la más antigua.',null),
('admin-navarra:20-e753c5b81e','admin-navarra',20,'¿Qué fuerza tiene la providencia de apremio en la Hacienda Pública de Navarra?','["La de un acto de trámite no recurrible", "La misma fuerza ejecutiva que la sentencia judicial", "La de un simple requerimiento de pago", "Fuerza ejecutiva solo tras su confirmación judicial"]'::jsonb,1,'Art. 13 LF 13/2007 Navarra','La providencia de apremio es título suficiente para el apremio y tiene la misma fuerza ejecutiva que la sentencia judicial.',null),
('admin-navarra:20-6c59685f8d','admin-navarra',20,'¿Pueden aplazarse las sanciones de tráfico y seguridad vial según la Ley Foral 13/2007?','["Sí, con garantía", "Sí, hasta un máximo de seis meses", "No, las solicitudes se archivan sin más trámite", "Sí, sin garantía si son de baja cuantía"]'::jsonb,2,'Art. 14 LF 13/2007 Navarra','Las sanciones en materia de transportes, tráfico y seguridad vial no son aplazables.',null),
('admin-navarra:20-17668f21f0','admin-navarra',20,'¿En qué plazo prescribe el derecho de la Hacienda Pública de Navarra a liquidar créditos a su favor?','["Cuatro años", "Tres años", "Diez años", "Cinco años"]'::jsonb,0,'Art. 16 LF 13/2007 Navarra','Salvo ley especial, prescribe a los cuatro años desde que el derecho pudo ejercitarse.',null),
('admin-navarra:20-9829763b4d','admin-navarra',20,'¿Cómo se aplica la prescripción de los derechos de la Hacienda Pública de Navarra?','["Solo por resolución judicial", "Solo si la alega el interesado en recurso", "Solo a instancia del deudor", "De oficio"]'::jsonb,3,'Art. 16 LF 13/2007 Navarra','La prescripción se interrumpe según la normativa tributaria foral y se aplica de oficio.',null),
('admin-navarra:20-c754755dd3','admin-navarra',20,'¿Qué tipo de interés de demora se aplica, salvo ley especial, a las cantidades adeudadas a la Hacienda Pública de Navarra?','["Un tipo fijo del 5 %", "El interés legal incrementado en un 25 %", "El interés legal del dinero", "El tipo de referencia del Banco Central Europeo"]'::jsonb,2,'Art. 18 LF 13/2007 Navarra','Salvo ley especial, el interés de demora es el interés legal del dinero de cada año.',null),
('admin-navarra:20-5e0695898d','admin-navarra',20,'¿Cuándo son exigibles las obligaciones de la Hacienda Pública de Navarra?','["Desde que el acreedor presenta la factura en el registro, aunque no exista crédito presupuestario", "Cuando resultan de la ejecución presupuestaria, de sentencia firme o de operaciones financieras autorizadas", "Cuando lo autoriza el Parlamento de Navarra", "Desde que se firma el contrato en todo caso"]'::jsonb,1,'Art. 21 LF 13/2007 Navarra','Solo son exigibles cuando resultan de la ejecución de los presupuestos, de sentencia judicial firme o de operaciones financieras legalmente autorizadas.',null),
('admin-navarra:20-18aafaed57','admin-navarra',20,'¿En qué plazo debe materializarse el pago derivado de una resolución judicial que condena a la Hacienda Pública de Navarra?','["Tres meses desde la notificación", "Seis meses desde la notificación", "Un mes desde la notificación", "Dos meses desde la firmeza"]'::jsonb,0,'Art. 23 LF 13/2007 Navarra','La materialización del pago debe realizarse dentro de los tres meses siguientes a la notificación de la resolución.',null),
('admin-navarra:20-2fd8d657bf','admin-navarra',20,'¿Desde cuándo debe la Administración navarra intereses de demora a su acreedor por falta de pago?','["Solo desde la reclamación judicial", "Si no paga en los seis meses siguientes", "Desde el día siguiente al vencimiento de la factura", "Si no paga en los dos meses siguientes a la notificación o reconocimiento"]'::jsonb,3,'Art. 24 LF 13/2007 Navarra','Si no paga dentro de los dos meses siguientes a la notificación o al reconocimiento de la obligación, debe intereses de demora.',null),
('admin-navarra:21-10d04f8c0b','admin-navarra',21,'¿Quién autoriza las generaciones de crédito en los Presupuestos de Navarra?','["El titular de cada Departamento", "El Consejero de Economía y Hacienda", "El Gobierno de Navarra", "El Parlamento de Navarra"]'::jsonb,1,'Art. 46 LF 13/2007 Navarra','Las generaciones de crédito deben ser autorizadas por el Consejero de Economía y Hacienda.',null),
('admin-navarra:21-527a8eb972','admin-navarra',21,'¿En qué créditos pueden generar crédito los ingresos por reembolso de préstamos según la Ley Foral 13/2007?','["En los créditos de gastos de personal", "En cualquier crédito del mismo Departamento", "Solo en los destinados a conceder nuevos préstamos", "En el Fondo de Contingencia"]'::jsonb,2,'Art. 46 LF 13/2007 Navarra','Los ingresos por reembolso de préstamos solo pueden generar crédito en los destinados a la concesión de nuevos préstamos.',null),
('admin-navarra:21-d9f06e1b49','admin-navarra',21,'¿Cuál de estos créditos es ampliable según la Ley Foral 13/2007?','["Los destinados a cubrir las prestaciones de las clases pasivas", "Los de gastos corrientes en bienes y servicios", "Los de inversiones reales nuevas", "Los de subvenciones de concurrencia competitiva"]'::jsonb,0,'Art. 47 LF 13/2007 Navarra','Son ampliables, entre otros, los de retribuciones por convenios, clases pasivas, endeudamiento y ejecución de sentencias.',null),
('admin-navarra:21-7fc208ffdf','admin-navarra',21,'Si hay que realizar un gasto inaplazable sin crédito en el presupuesto de Navarra, ¿qué se tramita?','["Un decreto foral de ampliación de crédito", "Una orden foral de generación de crédito", "Un proyecto de Ley Foral de crédito extraordinario", "Un acuerdo del Gobierno de transferencia de crédito"]'::jsonb,2,'Art. 48 LF 13/2007 Navarra','Si no existe crédito, se remite al Parlamento un proyecto de Ley Foral de crédito extraordinario; si es insuficiente, de suplemento de crédito.',null),
('admin-navarra:21-5188740ab1','admin-navarra',21,'¿Qué créditos del ejercicio anterior pueden incorporarse según la Ley Foral 13/2007?','["Solo los de gastos de personal", "Los de compromisos de gasto adquiridos antes del último mes del ejercicio", "Todos los créditos no gastados del ejercicio anterior", "Los de compromisos adquiridos en diciembre"]'::jsonb,1,'Art. 49 LF 13/2007 Navarra','Pueden incorporarse, entre otros, los que amparen compromisos de gasto adquiridos antes del último mes del ejercicio.',null),
('admin-navarra:21-afa995c492','admin-navarra',21,'¿Cuál es la primera fase de ejecución del presupuesto de gastos en Navarra?','["La propuesta de pago", "El reconocimiento de la obligación", "La disposición del gasto", "La autorización del gasto"]'::jsonb,3,'Art. 52 LF 13/2007 Navarra','Las fases son autorización, disposición, reconocimiento de la obligación, propuesta de pago y materialización del pago.',null),
('admin-navarra:21-ecd1fa3750','admin-navarra',21,'¿Qué fase de ejecución del gasto supone adquirir un compromiso económico con un tercero determinado?','["El reconocimiento de la obligación", "La disposición del gasto", "La materialización del pago", "La autorización del gasto"]'::jsonb,1,'Art. 52 LF 13/2007 Navarra','La disposición es el acto por el que se adquiere un compromiso económico con un tercero determinado, reservando el crédito por cuantía cierta.',null),
('admin-navarra:21-67dadd1ba8','admin-navarra',21,'¿A quién corresponden la propuesta y la materialización de los pagos en la Administración foral?','["Al Gobierno de Navarra", "Al Departamento gestor del gasto", "A la Intervención Delegada de cada Departamento", "Al Departamento de Economía y Hacienda"]'::jsonb,3,'Art. 53 LF 13/2007 Navarra','La propuesta y materialización de los pagos corresponde al Departamento de Economía y Hacienda.',null),
('admin-navarra:21-ced238b988','admin-navarra',21,'¿En qué plazo deben rendirse, como regla, las cuentas de las órdenes de pago a justificar en Navarra?','["Dos meses", "Un mes", "Tres meses", "Seis meses"]'::jsonb,0,'Art. 56 LF 13/2007 Navarra','El plazo de rendición es de dos meses, salvo los pagos de expropiaciones, que pueden rendirse en seis meses.',null),
('admin-navarra:21-0eb3df35b3','admin-navarra',21,'¿En qué fecha se liquidan los Presupuestos de Navarra en cuanto al reconocimiento de derechos y obligaciones?','["El 31 de enero del año siguiente", "El 31 de marzo del año siguiente", "El 31 de diciembre del año natural correspondiente", "El 30 de junio del año siguiente"]'::jsonb,2,'Art. 58 LF 13/2007 Navarra','Los Presupuestos se liquidan, en cuanto al reconocimiento de derechos y obligaciones, el 31 de diciembre.',null),
('admin-navarra:21-5013020188','admin-navarra',21,'¿Con qué periodicidad remite el Departamento de Economía y Hacienda al Parlamento el estado de ejecución de los Presupuestos?','["Trimestral", "Semestral", "Mensual", "Anual, con la Cuenta General"]'::jsonb,0,'Art. 59 LF 13/2007 Navarra','Se remite en el primer mes de cada trimestre el estado de ejecución del trimestre anterior.',null),
('admin-navarra:21-eeddf8f521','admin-navarra',21,'Según la Ley Foral 13/2007, ¿con qué periodo coincide el ejercicio presupuestario de Navarra?','["Con el periodo de sesiones del Parlamento", "Del 1 de julio al 30 de junio", "Con la legislatura", "Con el año natural"]'::jsonb,3,'Art. 28 LF 13/2007 Navarra','El ejercicio presupuestario coincide con el año natural.',null),
('admin-navarra:21-ea937b7612','admin-navarra',21,'¿Qué incluye el Estado de Gastos de los presupuestos de la Administración foral, separadamente?','["Las previsiones de ingresos tributarios", "La cuenta consolidada del sector público", "Los Beneficios Fiscales y los Compromisos de Gasto de Carácter Plurianual", "Los estados financieros de previsión de las sociedades públicas de la Comunidad Foral"]'::jsonb,2,'Art. 29 LF 13/2007 Navarra','Del Estado de Gastos forman parte, separadamente, los Beneficios Fiscales y los Compromisos de Gasto de Carácter Plurianual.',null),
('admin-navarra:21-fa53c19c44','admin-navarra',21,'Según la Ley Foral 13/2007, ¿cómo se elaboran los Presupuestos Generales de Navarra?','["Por Departamentos sin clasificación funcional", "Por programas", "Por objetivos de déficit exclusivamente", "Por capítulos de ingresos"]'::jsonb,1,'Art. 31 LF 13/2007 Navarra','Se elaboran por programas, constituidos por partidas de gasto y de ingreso, que pueden desagregarse en proyectos.',null),
('admin-navarra:21-a892aff0e1','admin-navarra',21,'¿Qué principio prohíbe atender obligaciones minorando los derechos a liquidar, salvo autorización por ley foral?','["El de temporalidad", "El de integridad", "El de especialidad cualitativa", "El de unidad de caja"]'::jsonb,1,'Art. 32 LF 13/2007 Navarra','El régimen de derechos y obligaciones se ajusta al principio de integridad: se aplican por su importe íntegro.',null),
('admin-navarra:21-380d8a9a15','admin-navarra',21,'¿Antes de qué fecha debe remitir el Gobierno de Navarra al Parlamento el proyecto de Ley Foral de Presupuestos?','["Antes del 15 de octubre", "Antes del 1 de octubre", "Antes del 30 de noviembre", "Antes del 1 de noviembre"]'::jsonb,3,'Art. 36 LF 13/2007 Navarra','Antes del primero de noviembre de cada año, el Gobierno remite al Parlamento el proyecto de Ley Foral de Presupuestos.',null),
('admin-navarra:21-19bd73f9b9','admin-navarra',21,'¿Qué ocurre si la Ley Foral de Presupuestos de Navarra no se aprueba antes del primer día del ejercicio?','["Se paralizan todos los gastos no obligatorios", "Se aplica una doceava parte de los créditos cada mes", "Se prorroga automáticamente la del ejercicio anterior", "El Gobierno aprueba un decreto de presupuestos provisional"]'::jsonb,2,'Art. 37 LF 13/2007 Navarra','Se considera automáticamente prorrogada la Ley Foral del ejercicio anterior hasta la entrada en vigor de la nueva.',null),
('admin-navarra:21-5384e89cf9','admin-navarra',21,'En la prórroga presupuestaria navarra, ¿qué se constituye con los créditos de programas que concluyeron el ejercicio anterior?','["El Fondo de Prórroga", "Un remanente de tesorería afectado", "El Fondo de Contingencia", "Una reserva para incorporaciones"]'::jsonb,0,'Art. 37 LF 13/2007 Navarra','Con su importe se constituye el Fondo de Prórroga, para obligaciones contractuales y retribuciones.',null),
('admin-navarra:21-0e51deaa8a','admin-navarra',21,'¿A qué nivel tienen, como regla, carácter vinculante los créditos de gastos corrientes en bienes y servicios en Navarra?','["A nivel de capítulo", "A nivel de artículo", "A nivel de programa", "A nivel de concepto"]'::jsonb,0,'Art. 38 LF 13/2007 Navarra','Con carácter general vinculan a nivel de concepto; personal, a nivel de artículo; y bienes corrientes y servicios, a nivel de capítulo.',null),
('admin-navarra:21-a3a9390f59','admin-navarra',21,'¿Qué consecuencia tienen los actos que comprometen gastos por encima de los créditos del Estado de gastos?','["Son anulables", "Son nulos de pleno derecho", "Son válidos pero generan responsabilidad", "Son ineficaces hasta que se habilite crédito"]'::jsonb,1,'Art. 39 LF 13/2007 Navarra','Son nulos de pleno derecho los actos y disposiciones que adquieran compromisos por encima del crédito.',null),
('admin-navarra:21-8a91908520','admin-navarra',21,'¿A cuántos ejercicios pueden imputarse, como regla, los gastos plurianuales en Navarra?','["No más de cuatro", "No más de tres", "No más de cinco", "No más de diez"]'::jsonb,2,'Art. 40 LF 13/2007 Navarra','El número de ejercicios no será superior a cinco, salvo los casos autorizados por norma con rango de ley.',null),
('admin-navarra:21-73d4ba20a2','admin-navarra',21,'¿Qué porcentaje de los créditos iniciales puede comprometerse en el ejercicio inmediato siguiente en un gasto plurianual navarro?','["El 50 %", "El 60 %", "El 80 %", "El 70 %"]'::jsonb,3,'Art. 40 LF 13/2007 Navarra','Los límites son el 70 % en el ejercicio siguiente, el 60 % en el segundo y el 50 % en los siguientes.',null),
('admin-navarra:21-ea65537e52','admin-navarra',21,'¿Qué importe de gasto plurianual imputable a ejercicios futuros exige autorización previa del Gobierno de Navarra?','["Superior a 300.000 euros", "Superior a 600.000 euros", "Superior a 100.000 euros", "Superior a 1.000.000 de euros"]'::jsonb,1,'Art. 40 LF 13/2007 Navarra','Los compromisos plurianuales con gasto futuro superior a 600.000 euros requieren autorización previa del Gobierno.',null),
('admin-navarra:21-c716421527','admin-navarra',21,'¿Qué ocurre con los créditos no afectados a obligaciones reconocidas el último día del ejercicio en Navarra?','["Se incorporan automáticamente al ejercicio siguiente", "Pasan al Fondo de Contingencia", "Se transfieren al Departamento de Hacienda", "Quedan anulados"]'::jsonb,3,'Art. 41 LF 13/2007 Navarra','Los créditos no afectados al cumplimiento de obligaciones ya reconocidas quedan anulados al final del ejercicio.',null),
('admin-navarra:21-88c44d70ee','admin-navarra',21,'¿Quién autoriza la utilización del Fondo de Contingencia en Navarra?','["El Gobierno de Navarra", "El Parlamento de Navarra", "El Consejero de Hacienda por sí solo", "La Cámara de Comptos"]'::jsonb,0,'Art. 42 LF 13/2007 Navarra','Su utilización debe autorizarla el Gobierno, que informa trimestralmente al Parlamento.',null),
('admin-navarra:21-f4afc37051','admin-navarra',21,'¿Con qué periodicidad informa el Gobierno al Parlamento de Navarra sobre la utilización del Fondo de Contingencia?','["Anual", "Semestral", "Trimestral", "Mensual"]'::jsonb,2,'Art. 42 LF 13/2007 Navarra','El Gobierno remite con periodicidad trimestral al Parlamento un informe sobre su utilización.',null),
('admin-navarra:21-b8a332fbc1','admin-navarra',21,'¿Cuál de estas NO es una modificación presupuestaria según la Ley Foral 13/2007?','["Los movimientos de fondos previstos en la ley de presupuestos", "Los suplementos de crédito", "Las incorporaciones de crédito", "Las generaciones de crédito"]'::jsonb,0,'Art. 43 LF 13/2007 Navarra','Las modificaciones son transferencias, generaciones, ampliaciones, incorporaciones, créditos extraordinarios y suplementos; los movimientos de fondos no lo son.',null),
('admin-navarra:21-fea79c1122','admin-navarra',21,'¿Qué son las transferencias de crédito según la Ley Foral 13/2007?','["Créditos para gastos sin dotación en el presupuesto", "Traspasos de dotaciones entre créditos de distinto nivel de vinculación", "Incrementos de crédito financiados con nuevos ingresos", "Traspasos dentro del mismo nivel de vinculación"]'::jsonb,1,'Art. 44 LF 13/2007 Navarra','Las transferencias son traspasos de dotaciones entre créditos de distinto nivel de vinculación.',null),
('admin-navarra:21-6ee043b9a9','admin-navarra',21,'¿Puede una transferencia de crédito minorar un crédito extraordinario concedido durante el ejercicio en Navarra?','["Sí, si no altera los objetivos del programa", "Sí, al final del ejercicio", "Sí, con autorización del Gobierno", "No"]'::jsonb,3,'Art. 44 LF 13/2007 Navarra','Las transferencias no pueden minorar los créditos extraordinarios concedidos durante el ejercicio.',null),
('admin-navarra:22-ce834d1302','admin-navarra',22,'¿Cuál de estos es un principio de la contratación pública enumerado en la Ley Foral 2/2018?','["Preferencia de empresas navarras", "Confidencialidad absoluta de las ofertas", "Reconocimiento mutuo", "Discrecionalidad técnica"]'::jsonb,2,'Art. 2 LF 2/2018 Navarra','Se aplican los principios de igualdad de trato, no discriminación, reconocimiento mutuo, proporcionalidad, transparencia e integridad, además de eficacia y eficiencia.',null),
('admin-navarra:22-b9147ff4f1','admin-navarra',22,'Según la Ley Foral 2/2018, ¿qué deben incluir de manera preceptiva los contratos públicos?','["La exigencia de clasificación empresarial", "Una cláusula de revisión de precios", "Una garantía provisional del 2 % y una cláusula de revisión de precios en todo caso", "Criterios de adjudicación y requerimientos de ejecución de carácter social o medioambiental"]'::jsonb,3,'Art. 2 LF 2/2018 Navarra','Para materializar el principio, los contratos deben incluir preceptivamente criterios de adjudicación y requerimientos de ejecución sociales o medioambientales.',null),
('admin-navarra:22-ddbaf469e8','admin-navarra',22,'¿Qué carácter tienen los contratos públicos según el art. 3 de la Ley Foral 2/2018?','["Onerosos y celebrados por escrito", "Onerosos, pudiendo celebrarse verbalmente", "Gratuitos u onerosos, verbales o escritos", "Gratuitos y celebrados por escrito"]'::jsonb,0,'Art. 3 LF 2/2018 Navarra','Son contratos públicos los contratos onerosos celebrados por escrito con entidades sometidas a la ley foral.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('admin-navarra:22-7a2e5fcf5e','admin-navarra',22,'¿Cuál es la duración máxima de una prohibición de contratar declarada conforme a la Ley Foral 2/2018?','["Ocho años", "Tres años", "Cinco años", "Dos años"]'::jsonb,2,'Art. 24 LF 2/2018 Navarra','El alcance y duración se fijan según el dolo y el daño, sin que la duración pueda exceder de cinco años.',null),
('admin-navarra:22-ca2e3c76aa','admin-navarra',22,'¿Qué contrato se considera de servicios, y no de suministro, en la Ley Foral 2/2018?','["La cesión del derecho de uso de programas estándar ya existentes en el mercado", "La adquisición de programas de ordenador desarrollados a medida", "El arrendamiento de sistemas de telecomunicaciones", "La adquisición de equipos informáticos"]'::jsonb,1,'Art. 29 LF 2/2018 Navarra','Los programas de ordenador desarrollados a medida se consideran contratos de servicios.',null),
('admin-navarra:22-964ef2c1b4','admin-navarra',22,'¿Qué servicios NO pueden ser objeto de un contrato de servicios según la Ley Foral 2/2018?','["Los que impliquen ejercicio de la autoridad inherente a los poderes públicos", "Los prestados al público en general", "Los de asesoramiento jurídico", "Los de limpieza y mantenimiento"]'::jsonb,0,'Art. 30 LF 2/2018 Navarra','No pueden ser objeto de contrato de servicios los que impliquen ejercicio de la autoridad inherente a los poderes públicos.',null),
('admin-navarra:22-010cfa41d4','admin-navarra',22,'Con pluralidad de criterios de adjudicación, ¿qué parte de la puntuación debe calcularse, como mínimo, con fórmulas objetivas?','["El 40 %", "El 50 %", "El 60 %", "El 75 %"]'::jsonb,1,'Art. 64 LF 2/2018 Navarra','Al menos el 50 % de la puntuación se calcula con fórmulas objetivas; en prestaciones artísticas o intelectuales, al menos el 20 %.',null),
('admin-navarra:22-2a35122ab5','admin-navarra',22,'¿Qué ponderación máxima pueden tener las mejoras como criterio de adjudicación en la Ley Foral 2/2018?','["El 15 % del total de puntos", "El 20 % del total de puntos", "El 10 % del total de puntos", "El 5 % del total de puntos"]'::jsonb,2,'Art. 64 LF 2/2018 Navarra','Las mejoras se usan con carácter excepcional y no pueden superar el 10 % del total de puntos.',null),
('admin-navarra:22-b6e51e2fb7','admin-navarra',22,'¿Qué ponderación mínima deben tener los criterios de adjudicación de carácter social en la Ley Foral 2/2018?','["El 5 % del total de puntos", "El 20 % del total de puntos", "El 25 % del total de puntos", "El 10 % del total de puntos"]'::jsonb,3,'Art. 64 LF 2/2018 Navarra','Los criterios sociales deben tener una ponderación de al menos el 10 % del total de puntos.',null),
('admin-navarra:22-c2e28ce2b6','admin-navarra',22,'¿Qué importe máximo puede tener la garantía provisional en la Ley Foral 2/2018?','["El 4 % del presupuesto de licitación", "El 3 % del presupuesto de licitación", "El 5 % del importe de adjudicación", "El 2 % del presupuesto de licitación"]'::jsonb,3,'Art. 70 LF 2/2018 Navarra','Excepcionalmente y de forma motivada puede exigirse garantía provisional de hasta el 2 % del presupuesto de licitación.',null),
('admin-navarra:22-c9f174367f','admin-navarra',22,'¿Qué importe máximo puede tener la garantía definitiva en la Ley Foral 2/2018?','["El 2 % del presupuesto de licitación", "El 5 % del importe de adjudicación", "El 4 % del importe de adjudicación", "El 10 % del importe de adjudicación"]'::jsonb,2,'Art. 70 LF 2/2018 Navarra','La garantía definitiva no puede exceder del 4 % del importe de adjudicación.',null),
('admin-navarra:22-7e88f32ee4','admin-navarra',22,'¿En qué procedimiento de la Ley Foral 2/2018 cualquier empresa o profesional interesado puede presentar oferta?','["Simplificado", "Abierto", "Negociado", "Restringido"]'::jsonb,1,'Art. 72 LF 2/2018 Navarra','El procedimiento abierto es aquel en el que cualquier empresa o profesional interesado puede presentar sus ofertas.',null),
('admin-navarra:22-68c75dceb6','admin-navarra',22,'En el procedimiento restringido de la Ley Foral 2/2018, ¿cuál es el número mínimo de empresas a invitar?','["Cinco", "Seis", "Tres", "Diez"]'::jsonb,0,'Art. 73 LF 2/2018 Navarra','El órgano de contratación señala el número mínimo de empresarios a invitar, que no puede ser inferior a cinco.',null),
('admin-navarra:22-cf89749f08','admin-navarra',22,'En el procedimiento negociado de la Ley Foral 2/2018, ¿cuál es el número mínimo de candidatos si se limita?','["Cuatro", "Cinco", "Dos", "Tres"]'::jsonb,3,'Art. 74 LF 2/2018 Navarra','Se puede limitar el número de candidatos admitidos a la negociación, que nunca será inferior a 3.',null),
('admin-navarra:22-4a7e3479ac','admin-navarra',22,'¿Hasta qué valor estimado puede usarse el procedimiento simplificado en contratos de obras según la Ley Foral 2/2018?','["Inferior a 500.000 euros", "Inferior a 200.000 euros", "Inferior a 100.000 euros", "Inferior a 60.000 euros"]'::jsonb,1,'Art. 80 LF 2/2018 Navarra','Solo en servicios y suministros de valor estimado inferior a 60.000 € y en obras inferiores a 200.000 €.',null),
('admin-navarra:22-1db051b174','admin-navarra',22,'¿A cuántas empresas debe solicitarse oferta, siempre que sea posible, en el procedimiento simplificado navarro?','["Al menos a seis", "Al menos a tres", "Al menos a cinco", "Al menos a dos"]'::jsonb,2,'Art. 80 LF 2/2018 Navarra','Se solicitarán, siempre que sea posible, ofertas al menos a 5 empresas o profesionales.',null),
('admin-navarra:22-c3c0e5df59','admin-navarra',22,'¿Qué valor estimado máximo tiene un contrato de suministros de menor cuantía en la Ley Foral 2/2018?','["15.000 euros", "18.000 euros", "40.000 euros", "6.000 euros"]'::jsonb,0,'Art. 81 LF 2/2018 Navarra','Son de menor cuantía los de valor estimado no superior a 15.000 € en suministros o servicios y 40.000 € en obras.',null),
('admin-navarra:22-01351416a1','admin-navarra',22,'¿Qué trámites exige un contrato de menor cuantía en la Ley Foral 2/2018?','["Solicitud de tres ofertas y reserva de crédito", "Publicación en el Portal de Contratación y factura", "La reserva de crédito, si procede, y la presentación de la factura", "Pliego de cláusulas administrativas particulares y resolución de adjudicación motivada"]'::jsonb,2,'Art. 81 LF 2/2018 Navarra','Solo exige la previa reserva de crédito, si fuese necesaria, y la presentación de la factura.',null),
('admin-navarra:22-ce9aa9b2cd','admin-navarra',22,'¿Cuántos miembros componen el Tribunal Administrativo de Contratos Públicos de Navarra?','["Un Presidente y cuatro vocales", "Tres vocales sin Presidente", "Un Presidente, un vocal y un secretario con voto", "Un Presidente y dos vocales"]'::jsonb,3,'Art. 121 LF 2/2018 Navarra','Está compuesto por un Presidente y dos vocales, designados por el Gobierno por seis años, sin reelección.',null),
('admin-navarra:22-708423c899','admin-navarra',22,'¿Por cuánto tiempo se designa a los miembros del Tribunal Administrativo de Contratos Públicos de Navarra?','["Seis años, renovables una vez", "Seis años, sin posible reelección", "Cinco años, sin posible reelección", "Cuatro años, renovables una vez"]'::jsonb,1,'Art. 121 LF 2/2018 Navarra','Son designados por un periodo de seis años, sin poder ser reelegidos.',null),
('admin-navarra:22-6488412861','admin-navarra',22,'¿Cómo se presenta la reclamación especial en materia de contratación pública en Navarra?','["Exclusivamente de forma telemática a través del Portal de Contratación, y es gratuita", "En cualquier registro, previo pago de una tasa", "Telemáticamente o en cualquier registro, con una tasa proporcional al valor estimado del contrato", "Por escrito ante el órgano de contratación"]'::jsonb,0,'Art. 122 LF 2/2018 Navarra','Se presenta exclusivamente por vía telemática en el Portal de Contratación de Navarra y es gratuita en todo caso.',null),
('admin-navarra:22-1f91798f0f','admin-navarra',22,'¿Qué carácter tiene la reclamación especial en materia de contratación pública en Navarra?','["Obligatorio y previo al contencioso", "Obligatorio solo para contratos armonizados", "Potestativo y sustitutivo", "Potestativo y acumulable al recurso de alzada"]'::jsonb,2,'Art. 124 LF 2/2018 Navarra','Tiene carácter potestativo y sustitutivo, impidiendo otro recurso administrativo simultáneo por el mismo motivo.',null),
('admin-navarra:22-e5c8996c66','admin-navarra',22,'¿Cuál es el plazo para interponer la reclamación especial en materia de contratación pública en Navarra?','["Diez días", "Un mes", "Quince días hábiles", "Veinte días naturales"]'::jsonb,0,'Art. 124 LF 2/2018 Navarra','El plazo de interposición es de diez días desde la publicación o notificación del acto, según el caso.',null),
('admin-navarra:22-6c4a722788','admin-navarra',22,'¿Qué efecto tiene la impugnación de la adjudicación ante el Tribunal Administrativo de Contratos Públicos de Navarra?','["La anulación provisional de la adjudicación", "La suspensión automática del acto hasta que el Tribunal resuelva", "La suspensión del acto solo si el reclamante presta garantía suficiente ante el Tribunal", "Ningún efecto suspensivo salvo petición expresa"]'::jsonb,1,'Art. 124 LF 2/2018 Navarra','La impugnación de actos de trámite o de la adjudicación conlleva la suspensión automática hasta el Acuerdo del Tribunal.',null),
('admin-navarra:22-eca5ff1d65','admin-navarra',22,'¿En qué plazo debe resolver el Tribunal Administrativo de Contratos Públicos de Navarra la reclamación especial?','["Tres meses desde su interposición", "Diez días hábiles desde su interposición", "Un mes desde su interposición", "Veinte días hábiles desde su interposición"]'::jsonb,3,'Art. 127 LF 2/2018 Navarra','Se resuelve en veinte días hábiles; si no, el interesado puede considerarla desestimada.',null),
('admin-navarra:22-4f517fd7ea','admin-navarra',22,'¿Qué importe puede tener la multa por temeridad o mala fe en una reclamación especial en Navarra?','["Entre 1.000 y 50.000 euros", "Entre 3.000 y 30.000 euros", "Entre 500 y 15.000 euros", "Entre 1.000 y 30.000 euros"]'::jsonb,3,'Art. 127 LF 2/2018 Navarra','La multa será de entre 1.000 y 30.000 euros, y solo si se desestiman totalmente las pretensiones.',null),
('admin-navarra:23-3b9b88ea2c','admin-navarra',23,'A falta de previsión en las bases, ¿en qué plazo máximo debe presentarse la cuenta justificativa de una subvención en Navarra?','["Tres meses desde que finaliza el plazo para realizar la actividad", "Un mes desde que finaliza la actividad", "Dos meses desde el pago", "Seis meses desde la concesión"]'::jsonb,0,'Art. 27 LF 11/2005 Navarra','A falta de previsión, la cuenta se presenta como máximo en tres meses desde la finalización del plazo de realización de la actividad.',null),
('admin-navarra:23-26e4901736','admin-navarra',23,'¿Qué subvenciones de capital exigen comprobación material de la inversión antes del pago en Navarra?','["Todas, cualquiera que sea su importe", "Las superiores a 60.000 euros", "Las superiores a 30.000 euros", "Las superiores a 150.000 euros"]'::jsonb,1,'Art. 29 LF 11/2005 Navarra','Las subvenciones de capital superiores a 60.000 euros exigen la comprobación material de la inversión, con acta o informe.',null),
('admin-navarra:23-22a4951a9e','admin-navarra',23,'¿Cuándo se abonan, con carácter general, las subvenciones según la Ley Foral 11/2005?','["En el momento de la concesión", "Al inicio de la actividad", "Una vez acreditada la realización de la actividad", "Por mitades, al conceder y al justificar"]'::jsonb,2,'Art. 32 LF 11/2005 Navarra','Con carácter general se abonan una vez acreditada la realización de la actividad o la adopción del comportamiento.',null),
('admin-navarra:23-7225250fbf','admin-navarra',23,'¿A partir de qué importe de anticipo deben exigirse garantías, como regla, a los beneficiarios distintos de las entidades sociales?','["Anticipos superiores a 60.000 euros", "Cualquier anticipo", "Anticipos superiores a 100.000 euros", "Anticipos superiores a 15.000 euros"]'::jsonb,0,'Art. 33 LF 11/2005 Navarra','Se establecen garantías en los anticipos superiores a 60.000 euros, salvo las excepciones previstas.',null),
('admin-navarra:23-749a6f5ec3','admin-navarra',23,'¿Cuál es una causa de nulidad de la resolución de concesión de una subvención en la Ley Foral 11/2005?','["La subcontratación no autorizada", "La falta de publicidad de la subvención concedida", "El retraso en el pago", "La carencia o insuficiencia de crédito"]'::jsonb,3,'Art. 34 LF 11/2005 Navarra','Son causas de nulidad las generales de la legislación de procedimiento y la carencia o insuficiencia de crédito.',null),
('admin-navarra:23-17d442c93e','admin-navarra',23,'¿Qué conlleva, además del reintegro, la obtención de una subvención falseando las condiciones?','["La pérdida automática de la condición de funcionario", "Solo la devolución del principal", "El interés de demora desde el pago hasta que se acuerda el reintegro", "Un recargo fijo del 20 %"]'::jsonb,2,'Art. 35 LF 11/2005 Navarra','Procede el reintegro y el interés de demora desde el pago hasta la fecha en que se acuerde la procedencia del reintegro.',null),
('admin-navarra:23-5f31be2efb','admin-navarra',23,'¿En qué plazo debe resolverse el expediente de reintegro de una subvención en Navarra?','["Tres meses", "Doce meses", "Seis meses", "Dieciocho meses"]'::jsonb,1,'Art. 35 LF 11/2005 Navarra','El expediente de reintegro debe resolverse en el plazo de doce meses.',null),
('admin-navarra:23-370f8fb767','admin-navarra',23,'¿Quién adopta la resolución de reintegro de una subvención en Navarra?','["El órgano concedente", "El Departamento de Economía y Hacienda", "La Cámara de Comptos", "La Intervención General"]'::jsonb,0,'Art. 35 LF 11/2005 Navarra','La resolución del reintegro la adopta el órgano concedente, previa instrucción de expediente.',null),
('admin-navarra:23-fc24e09c84','admin-navarra',23,'¿Cómo responden los administradores de sociedades mercantiles de la obligación de reintegro que se les imputa?','["No responden", "Mancomunadamente", "Subsidiariamente", "Solidariamente"]'::jsonb,2,'Art. 37 LF 11/2005 Navarra','Los administradores que no actuaron para cumplir las obligaciones responden subsidiariamente del reintegro.',null),
('admin-navarra:23-7902911735','admin-navarra',23,'¿Quién ejerce el control financiero de las subvenciones concedidas por la Administración foral?','["La Cámara de Comptos, en exclusiva", "El órgano gestor de cada subvención", "El Parlamento de Navarra", "El Departamento de Economía y Hacienda, a través de la Intervención General"]'::jsonb,3,'Art. 40 LF 11/2005 Navarra','El control financiero lo ejerce el Departamento de Economía y Hacienda a través de la Intervención General.',null),
('admin-navarra:23-7adb2a0f70','admin-navarra',23,'¿Cuál de estos supuestos NO tiene carácter de subvención según la Ley Foral 11/2005?','["Las ayudas a empresas para inversión", "Los beneficios fiscales", "Las ayudas para proyectos de cooperación al desarrollo", "Las ayudas a asociaciones culturales por convocatoria"]'::jsonb,1,'Art. 2 LF 11/2005 Navarra','No son subvenciones, entre otros, los beneficios fiscales, las indemnizaciones por responsabilidad patrimonial y los conciertos educativos.',null),
('admin-navarra:23-9f60da631e','admin-navarra',23,'¿Qué requisito NO es propio de una subvención según la Ley Foral 11/2005?','["Que sea una disposición dineraria", "Que esté sujeta al cumplimiento de un objetivo o actividad", "Que fomente una actividad de utilidad pública o interés social", "Que exista una contraprestación directa del beneficiario"]'::jsonb,3,'Art. 2 LF 11/2005 Navarra','La subvención se entrega sin contraprestación directa de los beneficiarios ni de terceros.',null),
('admin-navarra:23-70d1642add','admin-navarra',23,'¿Qué importe de subvención exige autorización previa del Gobierno de Navarra según la Ley Foral 11/2005?','["Superior a un millón de euros", "Superior a dos millones de euros", "Superior a 300.000 euros", "Superior a 600.000 euros"]'::jsonb,0,'Art. 7 LF 11/2005 Navarra','Es necesario acuerdo del Gobierno para autorizar subvenciones de importe superior a un millón de euros.',null),
('admin-navarra:23-e7e4bfe8cf','admin-navarra',23,'¿Cuál es el plazo máximo de vigencia del convenio con una entidad colaboradora según la Ley Foral 11/2005?','["Dos años", "Cinco años", "Cuatro años", "Seis años"]'::jsonb,2,'Art. 11 LF 11/2005 Navarra','El convenio no puede superar cuatro años, salvo en la subsidiación de intereses de préstamos.',null),
('admin-navarra:23-645e60a0b2','admin-navarra',23,'¿Cuándo debe estar el beneficiario al corriente de sus obligaciones tributarias y con la Seguridad Social?','["En el momento de presentar la solicitud", "En el momento en que se dicta la propuesta de resolución de concesión", "En el momento del último pago", "En el momento de la justificación final de la subvención y del último pago"]'::jsonb,1,'Art. 9 LF 11/2005 Navarra','Debe estar al corriente en el momento en que se dicte la propuesta de resolución de concesión.',null),
('admin-navarra:23-da0119c48f','admin-navarra',23,'¿Qué duración máxima tiene la prohibición de obtener subvenciones no derivada de sentencia firme en la Ley Foral 11/2005?','["Dos años", "Tres años", "Diez años", "Cinco años"]'::jsonb,3,'Art. 13 LF 11/2005 Navarra','Si no deriva de sentencia firme, su alcance no puede exceder de cinco años.',null),
('admin-navarra:23-ebbb518cf1','admin-navarra',23,'¿Cómo puede acreditarse no estar incurso en las prohibiciones para ser beneficiario en Navarra?','["Mediante declaración responsable del solicitante", "Mediante informe de la entidad colaboradora", "Mediante acta notarial", "Solo mediante certificados oficiales"]'::jsonb,0,'Art. 13 LF 11/2005 Navarra','Puede realizarse mediante declaración responsable, sin perjuicio de que las bases fijen medios específicos.',null),
('admin-navarra:23-9afb624689','admin-navarra',23,'¿Qué límite tienen las subvenciones compatibles para una misma actividad según la Ley Foral 11/2005?','["No pueden superar el 80 % del coste", "No tienen límite si proceden de distintas Administraciones Públicas o entidades", "Junto con otros ingresos no pueden superar el coste de la actividad", "No pueden superar el 50 % del coste"]'::jsonb,2,'Art. 16 LF 11/2005 Navarra','El importe, aislado o junto con otras ayudas o recursos, no puede superar el coste de la actividad.',null),
('admin-navarra:23-fa45bf5e3c','admin-navarra',23,'¿Cuál es el procedimiento ordinario de concesión de subvenciones según la Ley Foral 11/2005?','["La concesión directa", "La concurrencia competitiva", "La evaluación individualizada", "El sorteo entre solicitantes"]'::jsonb,1,'Art. 17 LF 11/2005 Navarra','El procedimiento ordinario es la concurrencia competitiva, salvo que el Gobierno autorice la evaluación individualizada.',null),
('admin-navarra:23-1f79069495','admin-navarra',23,'¿Qué subvenciones pueden concederse de forma directa según la Ley Foral 11/2005?','["Las solicitadas por entidades locales", "Las de importe inferior a 3.000 euros, sin necesidad de bases reguladoras", "Las previstas nominativamente en la Ley Foral de Presupuestos", "Las de carácter plurianual"]'::jsonb,2,'Art. 17 LF 11/2005 Navarra','Pueden concederse de forma directa las nominativas, las impuestas por norma legal y, excepcionalmente, las de destinatario único.',null),
('admin-navarra:23-0881eee55d','admin-navarra',23,'¿Antes de qué fecha debe resolverse la concesión de subvenciones a entidades de acción social en Navarra?','["Antes del 30 de junio de cada año", "Antes del 31 de marzo de cada año", "Antes del 28 de febrero de cada año", "Antes del 30 de abril de cada año"]'::jsonb,1,'Art. 17 LF 11/2005 Navarra','Se inicia en enero y la resolución de concesión debe dictarse antes del 31 de marzo de cada año.',null),
('admin-navarra:23-57738b4c9e','admin-navarra',23,'Si la convocatoria no fija plazo para resolver, ¿cuándo se entiende desestimada una solicitud de subvención en Navarra?','["A los tres meses desde el fin del plazo de solicitudes", "A los seis meses desde la presentación de la solicitud en el registro", "Al mes desde la presentación", "Nunca, rige el silencio positivo"]'::jsonb,0,'Art. 23 LF 11/2005 Navarra','En ausencia de plazo, se entiende desestimada pasados tres meses desde la fecha final del plazo de presentación.',null),
('admin-navarra:23-c63721b5c9','admin-navarra',23,'Si las bases no fijan porcentaje, ¿qué parte de la actividad subvencionada puede subcontratar el beneficiario en Navarra?','["Hasta el 100 %", "Hasta el 30 %", "Hasta el 20 %", "Hasta el 50 %"]'::jsonb,3,'Art. 26 LF 11/2005 Navarra','Si las bases no lo fijan, puede subcontratar hasta un 50 % del importe de la actividad subvencionada.',null),
('admin-navarra:23-1672f01e5c','admin-navarra',23,'¿Cuándo debe formalizarse por escrito la subcontratación de una actividad subvencionada en Navarra?','["Si excede del 10 % de la subvención", "Si excede del 20 % de la subvención y supera 60.000 euros", "Si supera 15.000 euros en todo caso", "Siempre que exista subcontratación"]'::jsonb,1,'Art. 26 LF 11/2005 Navarra','Cuando lo concertado exceda del 20 % de la subvención y sea superior a 60.000 euros, se exige contrato escrito.',null),
